package com.woodycode23.lifetracker;

/**
 * The calorie rule, in one place.
 *
 * <p>OSRS has no nutrition data, so any figure is invented and the only honest approach is to
 * invent it transparently. Food is worth the hitpoints it restores times a factor; a potion dose is
 * worth a small flat amount, because most potions restore nothing and would otherwise be free.
 *
 * <p>The default factor of 10 is chosen rather than picked: it puts the staples within roughly a
 * tenth of the real world calorie count for the same fish, which a derived rule has no right to do
 * and a hand written table would need constant maintenance to achieve.
 */
public final class Calories
{
	/** Food energy for one item, from the hitpoints it restores. Damaging items are worth nothing. */
	public static long fromHealing(int hitpointsRestored, int count, int kcalPerHitpoint)
	{
		if (hitpointsRestored <= 0 || count <= 0)
		{
			return 0;
		}
		return (long) hitpointsRestored * count * kcalPerHitpoint;
	}

	/** Energy for sipped doses, which the healing rule would otherwise price at nothing. */
	public static long fromDoses(int doses, int kcalPerDose)
	{
		if (doses <= 0 || kcalPerDose <= 0)
		{
			return 0;
		}
		return (long) doses * kcalPerDose;
	}

	private Calories()
	{
	}
}

package com.woodycode23.lifetracker;

import java.util.ArrayList;
import java.util.List;
import com.woodycode23.lifetracker.stats.StatDef;
import com.woodycode23.lifetracker.stats.StatUnit;
import com.woodycode23.lifetracker.stats.Stats;

/**
 * Turns counters into sentences a person can picture.
 *
 * <p>Every comparison here is arithmetic on a fixed, checkable quantity: a marathon is 42.195km,
 * a running track lap is 400m, the Earth is 40,075km around, a full potion is four doses, a
 * maxed hitpoints level is 99. The one soft number is how big a game square is in the real
 * world, which has no official answer and is therefore a config knob rather than a claim.
 */
public final class Comparisons
{
	private static final double MARATHON_METRES = 42_195d;
	private static final double TRACK_LAP_METRES = 400d;
	private static final double EARTH_CIRCUMFERENCE_METRES = 40_075_000d;

	private static final int DOSES_PER_POTION = 4;
	private static final int MAX_HITPOINTS = 99;

	/** The reference intake used on nutrition labels. */
	private static final int KCAL_PER_DAY = 2_000;
	/** McDonald's published figure for a Big Mac. */
	private static final int KCAL_PER_BIG_MAC = 550;
	/** The long standing rule of thumb for a pound of body fat. */
	private static final int KCAL_PER_POUND_OF_FAT = 3_500;

	/** Comparison lines for one stat, or empty when the number is too small to be interesting. */
	public static List<String> forStat(StatDef def, long value, int centimetresPerTile)
	{
		List<String> out = new ArrayList<>();
		if (value <= 0)
		{
			return out;
		}

		if (def.getUnit() == StatUnit.TILES)
		{
			addDistance(out, value, centimetresPerTile);
		}
		else if (def.getUnit() == StatUnit.CALORIES)
		{
			addCalories(out, value);
		}
		else if (Stats.POTION_DOSES.equals(def.getId()))
		{
			out.add(String.format("%,.1f full potions", value / (double) DOSES_PER_POTION));
		}
		else if (Stats.DAMAGE_DEALT.equals(def.getId()) || Stats.DAMAGE_TAKEN.equals(def.getId()))
		{
			long lives = value / MAX_HITPOINTS;
			if (lives > 0)
			{
				out.add(String.format("%,d full %d hitpoint healthbars", lives, MAX_HITPOINTS));
			}
		}
		else if (Stats.FOOD_HEALED.equals(def.getId()))
		{
			long heals = value / (MAX_HITPOINTS - 1);
			if (heals > 0)
			{
				out.add(String.format("%,d heals from 1 hitpoint to %d", heals, MAX_HITPOINTS));
			}
		}
		else if (def.getUnit() == StatUnit.TICKS)
		{
			addDuration(out, value);
		}

		return out;
	}

	private static void addDistance(List<String> out, long tiles, int centimetresPerTile)
	{
		double metres = tiles * (centimetresPerTile / 100d);

		if (metres < 1_000)
		{
			out.add(String.format("%,.0f metres", metres));
		}
		else
		{
			out.add(String.format("%,.2f km", metres / 1000d));
		}

		if (metres >= EARTH_CIRCUMFERENCE_METRES / 100)
		{
			out.add(String.format("%,.2f laps of the Earth", metres / EARTH_CIRCUMFERENCE_METRES));
		}
		else if (metres >= MARATHON_METRES)
		{
			out.add(String.format("%,.1f marathons", metres / MARATHON_METRES));
		}
		else if (metres >= TRACK_LAP_METRES)
		{
			out.add(String.format("%,.1f laps of a running track", metres / TRACK_LAP_METRES));
		}
	}

	/** The point of the calorie count. Small totals get the Big Mac, large ones get the diet. */
	private static void addCalories(List<String> out, long calories)
	{
		if (calories >= KCAL_PER_POUND_OF_FAT * 10L)
		{
			out.add(String.format("%,.1f pounds of body fat", calories / (double) KCAL_PER_POUND_OF_FAT));
		}
		else if (calories >= KCAL_PER_DAY)
		{
			out.add(String.format("%,.1f days of eating", calories / (double) KCAL_PER_DAY));
		}
		else
		{
			out.add(String.format("%,.1f Big Macs", calories / (double) KCAL_PER_BIG_MAC));
		}
	}

	private static void addDuration(List<String> out, long ticks)
	{
		double hours = (ticks * 0.6d) / 3600d;
		if (hours >= 24)
		{
			out.add(String.format("%,.1f full days", hours / 24d));
		}
		else if (hours >= 1)
		{
			out.add(String.format("%,.1f hours", hours));
		}
	}

	private Comparisons()
	{
	}
}

package com.woodycode23.lifetracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import com.woodycode23.lifetracker.stats.Period;
import com.woodycode23.lifetracker.stats.StatStore;

@ConfigGroup(StatStore.CONFIG_GROUP)
public interface LifeTrackerConfig extends Config
{
	@ConfigSection(
		name = "Tracking",
		description = "Which families of stats to record",
		position = 0
	)
	String trackingSection = "tracking";

	@ConfigSection(
		name = "Display",
		description = "How the panel presents your stats",
		position = 1
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Milestones",
		description = "Chat notifications when you pass a round number",
		position = 2
	)
	String milestonesSection = "milestones";

	@ConfigItem(
		keyName = "trackMovement",
		name = "Movement",
		description = "Tiles walked, ran and sailed, and teleports taken",
		section = trackingSection,
		position = 0
	)
	default boolean trackMovement()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackConsumables",
		name = "Consumables",
		description = "Potion doses by type, food eaten and hitpoints healed",
		section = trackingSection,
		position = 1
	)
	default boolean trackConsumables()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackPrayer",
		name = "Prayer",
		description = "Uptime per prayer and prayer points drained. Overhead uptime covers the six classic overheads plus the Ruinous dampen prayers",
		section = trackingSection,
		position = 2
	)
	default boolean trackPrayer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackSession",
		name = "Session",
		description = "Time played, active versus idle time, and logins",
		section = trackingSection,
		position = 3
	)
	default boolean trackSession()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackCombat",
		name = "Combat and economy",
		description = "Damage dealt and taken, deaths, kills, special attacks and alchemy casts",
		section = trackingSection,
		position = 4
	)
	default boolean trackCombat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "defaultPeriod",
		name = "Default period",
		description = "Which time window the panel opens on",
		section = displaySection,
		position = 0
	)
	default Period defaultPeriod()
	{
		return Period.DAY;
	}

	@ConfigItem(
		keyName = "showComparisons",
		name = "Show comparisons",
		description = "Translate raw counters into distances, durations and other real world equivalents",
		section = displaySection,
		position = 1
	)
	default boolean showComparisons()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSparklines",
		name = "Show trend bars",
		description = "Draw a small bar chart of the period next to each stat",
		section = displaySection,
		position = 2
	)
	default boolean showSparklines()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showZeroStats",
		name = "Show untouched stats",
		description = "List stats you have never recorded anything for instead of hiding them",
		section = displaySection,
		position = 3
	)
	default boolean showZeroStats()
	{
		return false;
	}

	@Range(min = 1, max = 500)
	@ConfigItem(
		keyName = "centimetresPerTile",
		name = "Tile size (cm)",
		description = "Assumed real world size of one game square, used only for distance comparisons. There is no official figure, so this is a knob rather than a fact",
		section = displaySection,
		position = 4
	)
	default int centimetresPerTile()
	{
		return 100;
	}

	@Range(min = 0, max = 200)
	@ConfigItem(
		keyName = "kcalPerHitpoint",
		name = "Calories per hitpoint",
		description = "Calories for each hitpoint a food restores. The default of 10 puts the staples within about a tenth of what the same fish really contains: shark 200, manta ray 220, karambwan 180, lobster 120",
		section = displaySection,
		position = 5
	)
	default int kcalPerHitpoint()
	{
		return 10;
	}

	@Range(min = 0, max = 200)
	@ConfigItem(
		keyName = "kcalPerPotionDose",
		name = "Calories per potion dose",
		description = "Calories for each dose sipped, since most potions restore no hitpoints and would otherwise count for nothing. A dose is a mouthful of syrup, hence the small default. Set to 0 to count food only",
		section = displaySection,
		position = 6
	)
	default int kcalPerPotionDose()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "milestoneNotifications",
		name = "Milestone messages",
		description = "Post a game chat message when a stat crosses a round number",
		section = milestonesSection,
		position = 0
	)
	default boolean milestoneNotifications()
	{
		return true;
	}
}

package com.woodycode23.lifetracker;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.itemstats.ItemStatChanges;
import com.woodycode23.lifetracker.stats.AccountStats;
import com.woodycode23.lifetracker.stats.StatCatalog;
import com.woodycode23.lifetracker.stats.StatSelection;
import com.woodycode23.lifetracker.stats.StatStore;
import com.woodycode23.lifetracker.trackers.CombatTracker;
import com.woodycode23.lifetracker.trackers.ConsumableTracker;
import com.woodycode23.lifetracker.trackers.MovementTracker;
import com.woodycode23.lifetracker.trackers.PrayerTracker;
import com.woodycode23.lifetracker.trackers.SessionTracker;
import com.woodycode23.lifetracker.trackers.Tracker;
import com.woodycode23.lifetracker.trackers.TrackerContext;
import com.woodycode23.lifetracker.ui.LifeTrackerPanel;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/**
 * Wiring and lifecycle.
 *
 * <p>The plugin itself records nothing. It owns the store, builds the trackers, and decides
 * when work that must not happen every tick actually happens: saving, milestone checks and
 * panel refreshes each run on their own interval.
 */
@PluginDescriptor(
	name = "Life Tracker",
	description = "Lifetime activity stats with day, week, month and year breakdowns",
	tags = {"stats", "tracker", "activity", "tiles", "steps", "potion", "prayer", "playtime", "history"}
)
@Slf4j
public class LifeTrackerPlugin extends Plugin
{
	/** Roughly 30 seconds. Saving is batched to keep config writes off the tick path. */
	private static final int FLUSH_INTERVAL_TICKS = 50;

	/** Roughly 1.8 seconds, which reads as live without churning Swing. */
	private static final int PANEL_REFRESH_INTERVAL_TICKS = 3;

	@Inject
	private Client client;

	@Inject
	private LifeTrackerConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	/**
	 * The heal value of every consumable in the game.
	 *
	 * <p>Deliberately the concrete table rather than {@code ItemStatChangesService}. That interface
	 * is bound inside the core Item Stats plugin's configure method, so only plugins sharing that
	 * injector can inject it; a sideloaded plugin gets its own injector and failed outright with
	 * "No implementation for ItemStatChangesService was bound". This class is a singleton with a
	 * non-private no-argument constructor, so Guice builds it just in time with no binding at all.
	 */
	@Inject
	private ItemStatChanges itemStatChanges;

	@Inject
	private EventBus eventBus;

	@Inject
	private Gson gson;

	private StatCatalog catalog;
	private StatStore store;
	private StatSelection selection;
	private TrackerContext context;
	private MilestoneEngine milestoneEngine;

	private final List<Tracker> trackers = new ArrayList<>();

	private LifeTrackerPanel panel;
	private NavigationButton navButton;

	private int tickCounter;

	@Provides
	LifeTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LifeTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		catalog = new StatCatalog();
		store = new StatStore(configManager, gson);
		store.load();

		selection = new StatSelection(configManager, gson);
		selection.load();

		context = new TrackerContext(store, catalog, config);
		milestoneEngine = new MilestoneEngine(catalog, config, chatMessageManager);

		trackers.clear();
		trackers.add(new MovementTracker(client, context));
		trackers.add(new ConsumableTracker(client, itemManager, itemStatChanges, context));
		trackers.add(new PrayerTracker(client, context));
		trackers.add(new SessionTracker(client, context));
		trackers.add(new CombatTracker(client, context));

		for (Tracker tracker : trackers)
		{
			eventBus.register(tracker);
		}

		panel = new LifeTrackerPanel(store, catalog, selection, config, this::onPanelReset);

		final BufferedImage icon = ImageUtil.loadImageResource(LifeTrackerPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Life Tracker")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		// Covers enabling the plugin mid-session, where no login event will arrive.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			activateAccount();
		}
	}

	@Override
	protected void shutDown()
	{
		for (Tracker tracker : trackers)
		{
			eventBus.unregister(tracker);
			tracker.reset();
		}
		trackers.clear();

		if (store != null)
		{
			store.flush(LocalDate.now());
			store.deactivate();
		}

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}

		panel = null;
		navButton = null;
		tickCounter = 0;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
			case CONNECTION_LOST:
				// Positional and inventory state from before the break must not be diffed
				// against state after it.
				resetTrackers();
				store.flush(LocalDate.now());
				store.deactivate();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (store.getActiveAccountKey() == null)
		{
			activateAccount();
		}

		tickCounter++;

		if (tickCounter % PANEL_REFRESH_INTERVAL_TICKS == 0 && panel != null)
		{
			panel.refresh();
		}

		if (tickCounter % FLUSH_INTERVAL_TICKS == 0)
		{
			LocalDate today = LocalDate.now();
			milestoneEngine.check(store.active());
			store.flush(today);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!StatStore.CONFIG_GROUP.equals(event.getGroup()) || panel == null)
		{
			return;
		}

		// Display settings change which rows exist and how they are drawn.
		switch (event.getKey())
		{
			case "showSparklines":
			case "showZeroStats":
			case "showComparisons":
			case "defaultPeriod":
				panel.rebuild();
				break;
			default:
				break;
		}
	}

	/**
	 * Binds the store to whoever is logged in. The local player is not populated the instant the
	 * game state flips, so this is retried each tick until a name is available.
	 */
	private void activateAccount()
	{
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null || local.getName().isEmpty())
		{
			return;
		}

		AccountStats stats = store.activate(local.getName(), LocalDate.now());
		milestoneEngine.initialiseBaseline(stats);

		if (panel != null)
		{
			panel.rebuild();
		}
	}

	private void resetTrackers()
	{
		for (Tracker tracker : trackers)
		{
			tracker.reset();
		}
	}

	private void onPanelReset()
	{
		resetTrackers();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			activateAccount();
		}
	}
}

package com.woodycode23.lifetracker;

import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import com.woodycode23.lifetracker.stats.AccountStats;
import com.woodycode23.lifetracker.stats.StatCatalog;
import com.woodycode23.lifetracker.stats.StatDef;
import com.woodycode23.lifetracker.stats.StatUnit;

/**
 * Announces round numbers.
 *
 * <p>Only headline stats are eligible, because a milestone for every individual potion family
 * would be noise rather than a moment.
 *
 * <p>Each account remembers the highest threshold it has passed per stat. On load that memory
 * is raised to whatever the current totals already justify, so installing the plugin on an
 * account with history, or restoring synced config from another machine, never dumps a wall of
 * retrospective congratulations into the chat box.
 */
public class MilestoneEngine
{
	private static final long[] COUNT_THRESHOLDS = {
		100, 500, 1_000, 5_000, 10_000, 50_000, 100_000, 500_000, 1_000_000, 5_000_000, 10_000_000
	};

	private static final long[] TILE_THRESHOLDS = {
		1_000, 10_000, 50_000, 100_000, 500_000, 1_000_000, 5_000_000, 10_000_000, 50_000_000
	};

	private static final int TICKS_PER_HOUR = 6_000;
	private static final long[] HOUR_THRESHOLDS = {1, 10, 50, 100, 250, 500, 1_000, 2_500, 5_000};

	private final StatCatalog catalog;
	private final LifeTrackerConfig config;
	private final ChatMessageManager chatMessageManager;

	@Inject
	public MilestoneEngine(StatCatalog catalog, LifeTrackerConfig config, ChatMessageManager chatMessageManager)
	{
		this.catalog = catalog;
		this.config = config;
		this.chatMessageManager = chatMessageManager;
	}

	/**
	 * Records where each stat already stands without announcing anything. Must run whenever an
	 * account's history is first brought into memory.
	 */
	public void initialiseBaseline(AccountStats stats)
	{
		for (StatDef def : catalog.headlines())
		{
			int reached = indexFor(def, stats.lifetime(def.getId()));
			stats.setMilestoneIndex(def.getId(), Math.max(stats.milestoneIndex(def.getId()), reached));
		}
	}

	/** Announces any threshold crossed since the last check. */
	public void check(AccountStats stats)
	{
		if (stats == null)
		{
			return;
		}

		for (StatDef def : catalog.headlines())
		{
			long value = stats.lifetime(def.getId());
			int reached = indexFor(def, value);
			int previous = stats.milestoneIndex(def.getId());

			if (reached <= previous)
			{
				continue;
			}

			stats.setMilestoneIndex(def.getId(), reached);

			if (config.milestoneNotifications())
			{
				announce(def, thresholds(def)[reached]);
			}
		}
	}

	private void announce(StatDef def, long threshold)
	{
		String amount = def.getUnit() == StatUnit.TICKS
			? StatUnit.formatDuration(threshold)
			: StatUnit.formatNumber(threshold);

		String message = "Life Tracker milestone: " + amount + " " + def.getDisplayName().toLowerCase() + ".";

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	/** Index of the highest threshold this value has passed, or -1 for none. */
	private int indexFor(StatDef def, long value)
	{
		long[] thresholds = thresholds(def);
		int index = -1;
		for (int i = 0; i < thresholds.length; i++)
		{
			if (value >= thresholds[i])
			{
				index = i;
			}
		}
		return index;
	}

	private static long[] thresholds(StatDef def)
	{
		switch (def.getUnit())
		{
			case TILES:
				return TILE_THRESHOLDS;
			case TICKS:
				return tickThresholds();
			default:
				return COUNT_THRESHOLDS;
		}
	}

	private static long[] tickThresholds()
	{
		long[] out = new long[HOUR_THRESHOLDS.length];
		for (int i = 0; i < HOUR_THRESHOLDS.length; i++)
		{
			out[i] = HOUR_THRESHOLDS[i] * TICKS_PER_HOUR;
		}
		return out;
	}
}

package com.woodycode23.lifetracker.stats;

import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import lombok.Getter;
import lombok.Setter;

/**
 * All tracked history for a single character.
 *
 * <p>Every increment lands in three places at once: the lifetime total, today's bucket and
 * this month's bucket. Keeping the monthly aggregate live rather than deriving it later is
 * what makes pruning safe: dropping a daily bucket is a plain delete that can never
 * double-count or lose a month's total.
 *
 * <p>Daily buckets are pruned past {@link #DAILY_RETENTION_DAYS} so the whole object stays
 * small enough to live inside a synced RuneLite config value. Monthly buckets and lifetime
 * totals are never lossy.
 *
 * <p>Field names are deliberately short: this is serialised straight to JSON, and the JSON is
 * what gets gzipped into config.
 */
public class AccountStats
{
	public static final int DAILY_RETENTION_DAYS = 90;
	private static final int CURRENT_VERSION = 1;

	private static final DateTimeFormatter DAY_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
	private static final DateTimeFormatter MONTH_FMT = DateTimeFormatter.ofPattern("yyyy-MM");

	/** Schema version, so a future format change can migrate instead of discarding history. */
	private int v = CURRENT_VERSION;

	/** Display name as last seen in game. The map key is the lowercased form of this. */
	@Getter
	@Setter
	private String name = "";

	private Map<String, Long> life = new HashMap<>();
	private Map<String, Map<String, Long>> days = new HashMap<>();
	private Map<String, Map<String, Long>> months = new HashMap<>();
	private Map<String, DayRecord> rec = new HashMap<>();
	private Map<String, Integer> ms = new HashMap<>();

	private String firstSeen;
	private String lastActiveDay;
	private int streakCurrent;
	private int streakBest;

	public static class DayRecord
	{
		public long value;
		public String day;

		DayRecord(long value, String day)
		{
			this.value = value;
			this.day = day;
		}
	}

	/** Gson can leave collections null if a saved blob predates a field. */
	public void ensureInitialised()
	{
		if (life == null)
		{
			life = new HashMap<>();
		}
		if (days == null)
		{
			days = new HashMap<>();
		}
		if (months == null)
		{
			months = new HashMap<>();
		}
		if (rec == null)
		{
			rec = new HashMap<>();
		}
		if (ms == null)
		{
			ms = new HashMap<>();
		}
		if (name == null)
		{
			name = "";
		}
		if (v <= 0)
		{
			v = CURRENT_VERSION;
		}
	}

	public void add(String statId, long amount, LocalDate today)
	{
		if (amount == 0)
		{
			return;
		}

		life.merge(statId, amount, Long::sum);
		days.computeIfAbsent(DAY_FMT.format(today), k -> new HashMap<>()).merge(statId, amount, Long::sum);
		months.computeIfAbsent(MONTH_FMT.format(today), k -> new HashMap<>()).merge(statId, amount, Long::sum);
	}

	public long lifetime(String statId)
	{
		return life.getOrDefault(statId, 0L);
	}

	public Map<String, Long> lifetimeAll()
	{
		return Collections.unmodifiableMap(life);
	}

	public long value(String statId, Period period, LocalDate today)
	{
		if (period == Period.ALL)
		{
			return lifetime(statId);
		}

		long total = 0;
		for (long v : series(statId, period, today))
		{
			total += v;
		}
		return total;
	}

	/**
	 * Oldest-to-newest values for the period, one entry per day (or per month for YEAR).
	 * Doubles as the sparkline series and, summed, as the period total.
	 */
	public long[] series(String statId, Period period, LocalDate today)
	{
		if (period == Period.ALL)
		{
			return monthlySeries(statId, today, 12);
		}
		if (period.isMonthly())
		{
			return monthlySeries(statId, today, period.getSpan());
		}
		return dailySeries(statId, today, period.getSpan());
	}

	private long[] dailySeries(String statId, LocalDate today, int dayCount)
	{
		long[] out = new long[dayCount];
		for (int i = 0; i < dayCount; i++)
		{
			LocalDate day = today.minusDays(dayCount - 1L - i);
			Map<String, Long> bucket = days.get(DAY_FMT.format(day));
			out[i] = bucket == null ? 0L : bucket.getOrDefault(statId, 0L);
		}
		return out;
	}

	private long[] monthlySeries(String statId, LocalDate today, int monthCount)
	{
		YearMonth current = YearMonth.from(today);
		long[] out = new long[monthCount];
		for (int i = 0; i < monthCount; i++)
		{
			YearMonth month = current.minusMonths(monthCount - 1L - i);
			Map<String, Long> bucket = months.get(MONTH_FMT.format(month));
			out[i] = bucket == null ? 0L : bucket.getOrDefault(statId, 0L);
		}
		return out;
	}

	/** Stat ids that have ever recorded a non-zero value. Drives which rows the panel shows. */
	public List<String> trackedStatIds()
	{
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, Long> e : life.entrySet())
		{
			if (e.getValue() != 0)
			{
				out.add(e.getKey());
			}
		}
		return out;
	}

	/**
	 * Refreshes best-day records from today's bucket. Called on flush rather than on every
	 * increment so it costs one pass over one day's stats a few times a minute.
	 */
	public void refreshRecords(LocalDate today)
	{
		Map<String, Long> bucket = days.get(DAY_FMT.format(today));
		if (bucket == null)
		{
			return;
		}

		String dayKey = DAY_FMT.format(today);
		for (Map.Entry<String, Long> e : bucket.entrySet())
		{
			DayRecord existing = rec.get(e.getKey());
			if (existing == null || e.getValue() > existing.value)
			{
				rec.put(e.getKey(), new DayRecord(e.getValue(), dayKey));
			}
		}
	}

	public DayRecord record(String statId)
	{
		return rec.get(statId);
	}

	/**
	 * Marks today as played and advances the streak. Safe to call repeatedly; only the first
	 * call on a given day changes anything.
	 */
	public void touchDay(LocalDate today)
	{
		String todayKey = DAY_FMT.format(today);
		if (todayKey.equals(lastActiveDay))
		{
			return;
		}

		if (firstSeen == null)
		{
			firstSeen = todayKey;
		}

		if (lastActiveDay != null && LocalDate.parse(lastActiveDay, DAY_FMT).plusDays(1).equals(today))
		{
			streakCurrent++;
		}
		else
		{
			streakCurrent = 1;
		}

		streakBest = Math.max(streakBest, streakCurrent);
		lastActiveDay = todayKey;
	}

	/**
	 * The streak as of today. Stored state only advances on login, so a streak that has since
	 * lapsed must read as broken rather than frozen at its last value.
	 */
	public int currentStreak(LocalDate today)
	{
		if (lastActiveDay == null)
		{
			return 0;
		}

		LocalDate last = LocalDate.parse(lastActiveDay, DAY_FMT);
		if (last.equals(today) || last.plusDays(1).equals(today))
		{
			return streakCurrent;
		}
		return 0;
	}

	public int bestStreak()
	{
		return streakBest;
	}

	public LocalDate firstSeen()
	{
		return firstSeen == null ? null : LocalDate.parse(firstSeen, DAY_FMT);
	}

	public int milestoneIndex(String statId)
	{
		return ms.getOrDefault(statId, -1);
	}

	public void setMilestoneIndex(String statId, int index)
	{
		ms.put(statId, index);
	}

	/**
	 * Erases the given stats everywhere: lifetime, every bucket, records and milestone progress.
	 * Used by the per-category reset, so a category starts genuinely from zero rather than
	 * showing zero today while an old total lurks in the all-time view.
	 */
	public void removeStats(Collection<String> statIds)
	{
		for (String id : statIds)
		{
			life.remove(id);
			rec.remove(id);
			ms.remove(id);
		}

		for (Map<String, Long> bucket : days.values())
		{
			bucket.keySet().removeAll(statIds);
		}
		for (Map<String, Long> bucket : months.values())
		{
			bucket.keySet().removeAll(statIds);
		}
	}

	/** Drops daily buckets past the retention window. Monthly totals already hold their content. */
	public void prune(LocalDate today)
	{
		LocalDate cutoff = today.minusDays(DAILY_RETENTION_DAYS);
		Iterator<String> it = days.keySet().iterator();
		while (it.hasNext())
		{
			String key = it.next();
			try
			{
				if (LocalDate.parse(key, DAY_FMT).isBefore(cutoff))
				{
					it.remove();
				}
			}
			catch (Exception e)
			{
				// Unparseable key from a corrupted blob: drop it rather than keep dead weight.
				it.remove();
			}
		}
	}
}

package com.woodycode23.lifetracker.stats;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The time windows the panel can show.
 *
 * <p>DAY/WEEK/MONTH are rolling windows read from daily buckets, which are only kept for
 * {@link AccountStats#DAILY_RETENTION_DAYS} days. YEAR reads monthly buckets, which are kept
 * forever, so the year view stays correct once the daily detail behind it has been pruned.
 */
@Getter
@RequiredArgsConstructor
public enum Period
{
	DAY("Today", 1),
	WEEK("Week", 7),
	MONTH("Month", 30),
	YEAR("Year", 12),
	ALL("All time", 0);

	private final String displayName;

	/** Days of history for DAY/WEEK/MONTH, months of history for YEAR, unused for ALL. */
	private final int span;

	public boolean isMonthly()
	{
		return this == YEAR;
	}

	/**
	 * The period a chart should plot for this selection.
	 *
	 * <p>Today on its own is a single value, and a one bar chart is just a filled rectangle. The
	 * day view therefore plots the week around it, so today's bar has something to be read
	 * against. The headline number stays today's either way.
	 */
	public Period chartPeriod()
	{
		return this == DAY ? WEEK : this;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.woodycode23.lifetracker.stats;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Registry of every stat the plugin knows how to display.
 *
 * <p>Fixed stats are registered once at construction. Potion families and individual prayers
 * are registered lazily the first time they are seen, which is what keeps the plugin from
 * needing a hardcoded item id table: a potion that does not exist yet still gets tracked
 * correctly the day it is added to the game.
 *
 * <p>Saved history can outlive a stat definition (a renamed potion, a stat pulled from a
 * later version). {@link #get(String)} therefore never returns null; it synthesises a
 * definition from the id so old numbers still render instead of silently vanishing.
 */
public class StatCatalog
{
	public static final int ORDER_DYNAMIC_PRIMARY = 10;
	public static final int ORDER_DYNAMIC_SECONDARY = 20;

	private final Map<String, StatDef> defs = new LinkedHashMap<>();

	public StatCatalog()
	{
		Stats.registerFixed(this);
	}

	public StatDef register(String id, String displayName, StatCategory category, StatUnit unit, int sortOrder, boolean headline)
	{
		StatDef def = new StatDef(id, displayName, category, unit, sortOrder, headline);
		defs.put(id, def);
		return def;
	}

	public boolean isRegistered(String id)
	{
		return defs.containsKey(id);
	}

	/**
	 * Never null. Unknown ids get a best-effort definition so history from a future or
	 * renamed stat is still readable.
	 */
	public StatDef get(String id)
	{
		StatDef def = defs.get(id);
		if (def != null)
		{
			return def;
		}
		return new StatDef(id, prettifyUnknown(id), categoryFromId(id), unitFromId(id), ORDER_DYNAMIC_SECONDARY, false);
	}

	public List<StatDef> byCategory(StatCategory category)
	{
		List<StatDef> out = new ArrayList<>();
		for (StatDef def : defs.values())
		{
			if (def.getCategory() == category)
			{
				out.add(def);
			}
		}
		out.sort(Comparator.comparingInt(StatDef::getSortOrder).thenComparing(StatDef::getDisplayName));
		return out;
	}

	public List<StatDef> headlines()
	{
		List<StatDef> out = new ArrayList<>();
		for (StatDef def : defs.values())
		{
			if (def.isHeadline())
			{
				out.add(def);
			}
		}
		return out;
	}

	/** Registers a potion family discovered from an item name, e.g. "Stamina potion". */
	public String registerPotion(String familyName)
	{
		String id = Stats.POTION_PREFIX + slug(familyName);
		if (!defs.containsKey(id))
		{
			register(id, familyName, StatCategory.CONSUMABLES, StatUnit.COUNT, ORDER_DYNAMIC_PRIMARY, false);
		}
		return id;
	}

	/** Registers a food discovered from an item name, e.g. "Shark". */
	public String registerFood(String itemName)
	{
		String id = Stats.FOOD_PREFIX + slug(itemName);
		if (!defs.containsKey(id))
		{
			register(id, itemName, StatCategory.CONSUMABLES, StatUnit.COUNT, ORDER_DYNAMIC_SECONDARY, false);
		}
		return id;
	}

	/** Registers uptime for one prayer. Overheads sort above the rest. */
	public String registerPrayer(String prayerName, boolean overhead)
	{
		String id = Stats.PRAYER_PREFIX + slug(prayerName);
		if (!defs.containsKey(id))
		{
			register(id, prayerName, StatCategory.PRAYER, StatUnit.TICKS,
				overhead ? ORDER_DYNAMIC_PRIMARY : ORDER_DYNAMIC_SECONDARY, false);
		}
		return id;
	}

	public static String slug(String name)
	{
		return name.toLowerCase(Locale.US).replaceAll("[^a-z0-9]+", "_").replaceAll("(^_|_$)", "");
	}

	private static StatCategory categoryFromId(String id)
	{
		if (id.startsWith(Stats.POTION_PREFIX) || id.startsWith(Stats.FOOD_PREFIX) || id.startsWith("con."))
		{
			return StatCategory.CONSUMABLES;
		}
		if (id.startsWith(Stats.PRAYER_PREFIX) || id.startsWith("pray."))
		{
			return StatCategory.PRAYER;
		}
		if (id.startsWith("move."))
		{
			return StatCategory.MOVEMENT;
		}
		if (id.startsWith("ses."))
		{
			return StatCategory.SESSION;
		}
		return StatCategory.COMBAT;
	}

	private static StatUnit unitFromId(String id)
	{
		if (id.startsWith(Stats.PRAYER_PREFIX) || id.startsWith("ses."))
		{
			return StatUnit.TICKS;
		}
		if (id.startsWith("move."))
		{
			return StatUnit.TILES;
		}
		return StatUnit.COUNT;
	}

	private static String prettifyUnknown(String id)
	{
		String tail = id.substring(id.lastIndexOf('.') + 1).replace('_', ' ');
		if (tail.isEmpty())
		{
			return id;
		}
		return Character.toUpperCase(tail.charAt(0)) + tail.substring(1);
	}
}

package com.woodycode23.lifetracker.stats;

import lombok.Getter;
