package com.woodycode23.lifetracker.stats;

import lombok.Value;

/**
 * Metadata for one tracked counter. Trackers only ever deal in the string id; everything
 * a human needs to read the number lives here.
 */
@Value
public class StatDef
{
	/**
	 * Stable storage key. Never change one of these after release or saved history for
	 * that stat is orphaned.
	 */
	String id;

	String displayName;

	StatCategory category;

	StatUnit unit;

	/** Lower sorts first inside its category. Dynamic stats all share one order and fall back to alphabetical. */
	int sortOrder;

	/** Headline stats get a summary card and comparison lines; the rest are plain rows. */
	boolean headline;

	public String format(long value)
	{
		return unit.format(value);
	}
}

package com.woodycode23.lifetracker.stats;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Which stats the summary shows.
 *
 * <p>Stored as the set of <em>hidden</em> ids rather than shown ones, which is what makes newly
 * discovered items appear on their own. Eat a food or drink a potion you have never had before and
 * it shows up immediately, because it cannot be in a set written before it existed. Storing shown
 * ids would mean every new item arrived invisible and had to be found and switched on.
 *
 * <p>This controls display only. Recording is governed by the category switches in the plugin's
 * RuneLite settings, so hiding a row never loses history and switching it back on brings the full
 * total with it.
 */
@Slf4j
public class StatSelection
{
	private static final String KEY_HIDDEN = "hiddenStats";

	private final ConfigManager configManager;
	private final Gson gson;
	private final Set<String> hidden = new HashSet<>();

	public StatSelection(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public boolean isVisible(String statId)
	{
		return !hidden.contains(statId);
	}

	public void setVisible(String statId, boolean visible)
	{
		if (visible)
		{
			hidden.remove(statId);
		}
		else
		{
			hidden.add(statId);
		}
		save();
	}

	public void setVisible(Collection<String> statIds, boolean visible)
	{
		if (visible)
		{
			hidden.removeAll(statIds);
		}
		else
		{
			hidden.addAll(statIds);
		}
		save();
	}

	public void load()
	{
		hidden.clear();

		if (configManager == null)
		{
			return;
		}

		String raw = configManager.getConfiguration(StatStore.CONFIG_GROUP, KEY_HIDDEN);
		if (raw == null || raw.isEmpty())
		{
			return;
		}

		try
		{
			Set<String> stored = gson.fromJson(raw, new TypeToken<Set<String>>()
			{
			}.getType());
			if (stored != null)
			{
				hidden.addAll(stored);
			}
		}
		catch (Exception e)
		{
			log.warn("Could not read hidden stat selection, showing everything", e);
		}
	}

	private void save()
	{
		if (configManager == null)
		{
			return;
		}
		configManager.setConfiguration(StatStore.CONFIG_GROUP, KEY_HIDDEN, gson.toJson(new ArrayList<>(hidden)));
	}
}

package com.woodycode23.lifetracker.stats;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Owns every account's history and its persistence.
 *
 * <p>Storage is a RuneLite config value per account rather than a file, because config values
 * are what RuneLite's profile sync carries between machines. That imposes a size budget, which
 * is why {@link AccountStats} prunes daily buckets and why the JSON is gzipped and base64'd
 * before it is written.
 *
 * <p>Writes are batched: trackers increment in memory on the client thread and the store is
 * flushed on an interval, at logout and at shutdown. Nothing touches config per game tick.
 */
@Slf4j
public class StatStore
{
	public static final String CONFIG_GROUP = "lifetracker";

	private static final String KEY_INDEX = "accounts";
	private static final String KEY_ACCOUNT_PREFIX = "acct.";

	/** Roughly where a single account's encoded blob stops being a polite thing to sync. */
	private static final int SIZE_WARN_BYTES = 64 * 1024;

	private final ConfigManager configManager;
	private final Gson gson;

	/** Lowercased display name -> history. Insertion ordered so the account dropdown is stable. */
	private final Map<String, AccountStats> accounts = new LinkedHashMap<>();
	private final Set<String> dirty = new HashSet<>();

	@Getter
	private String activeAccountKey;

	public StatStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	// -- account lifecycle ------------------------------------------------

	public static String keyFor(String displayName)
	{
		return displayName.toLowerCase(Locale.US).trim();
	}

	/** Points the store at a character, creating its history on first sight. */
	public AccountStats activate(String displayName, LocalDate today)
	{
		String key = keyFor(displayName);
		AccountStats stats = accounts.computeIfAbsent(key, k -> {
			AccountStats fresh = new AccountStats();
			fresh.ensureInitialised();
			return fresh;
		});

		stats.setName(displayName);
		stats.touchDay(today);
		stats.prune(today);

		activeAccountKey = key;
		dirty.add(key);
		return stats;
	}

	public void deactivate()
	{
		activeAccountKey = null;
	}

	public AccountStats active()
	{
		return activeAccountKey == null ? null : accounts.get(activeAccountKey);
	}

	public AccountStats get(String accountKey)
	{
		return accounts.get(accountKey);
	}

	/** Display names in dropdown order. */
	public List<String> accountNames()
	{
		List<String> out = new ArrayList<>();
		for (AccountStats stats : accounts.values())
		{
			out.add(stats.getName());
		}
		return out;
	}

	public boolean isEmpty()
	{
		return accounts.isEmpty();
	}

	// -- writing ----------------------------------------------------------

	public void add(String statId, long amount, LocalDate today)
	{
		AccountStats stats = active();
		if (stats == null || amount == 0)
		{
			return;
		}

		stats.add(statId, amount, today);
		dirty.add(activeAccountKey);
	}

	// -- reading ----------------------------------------------------------

	/** Null accountKey means every account combined. */
	public long value(String accountKey, String statId, Period period, LocalDate today)
	{
		if (accountKey != null)
		{
			AccountStats stats = accounts.get(accountKey);
			return stats == null ? 0L : stats.value(statId, period, today);
		}

		long total = 0;
		for (AccountStats stats : accounts.values())
		{
			total += stats.value(statId, period, today);
		}
		return total;
	}

	public long[] series(String accountKey, String statId, Period period, LocalDate today)
	{
		if (accountKey != null)
		{
			AccountStats stats = accounts.get(accountKey);
			return stats == null ? new long[0] : stats.series(statId, period, today);
		}

		long[] combined = null;
		for (AccountStats stats : accounts.values())
		{
			long[] one = stats.series(statId, period, today);
			if (combined == null)
			{
				combined = one.clone();
				continue;
			}
			for (int i = 0; i < combined.length && i < one.length; i++)
			{
				combined[i] += one[i];
			}
		}
		return combined == null ? new long[0] : combined;
	}

	/** Every stat id with history, across one account or all of them. */
	public Set<String> trackedStatIds(String accountKey)
	{
		Set<String> out = new HashSet<>();
		for (AccountStats stats : forKey(accountKey))
		{
			out.addAll(stats.trackedStatIds());
		}
		return out;
	}

	/** Best single day for a stat. Across all accounts this is the best day any of them had. */
	public AccountStats.DayRecord record(String accountKey, String statId)
	{
		AccountStats.DayRecord best = null;
		for (AccountStats stats : forKey(accountKey))
		{
			AccountStats.DayRecord candidate = stats.record(statId);
			if (candidate != null && (best == null || candidate.value > best.value))
			{
				best = candidate;
			}
		}
		return best;
	}

	public int currentStreak(String accountKey, LocalDate today)
	{
		int best = 0;
		for (AccountStats stats : forKey(accountKey))
		{
			best = Math.max(best, stats.currentStreak(today));
		}
		return best;
	}

	public int bestStreak(String accountKey)
	{
		int best = 0;
		for (AccountStats stats : forKey(accountKey))
		{
			best = Math.max(best, stats.bestStreak());
		}
		return best;
	}

	private Collection<AccountStats> forKey(String accountKey)
	{
		if (accountKey == null)
		{
			return accounts.values();
		}
		AccountStats stats = accounts.get(accountKey);
		return stats == null ? new ArrayList<>() : java.util.Collections.singletonList(stats);
	}

	// -- persistence ------------------------------------------------------

	public void load()
	{
		accounts.clear();
		dirty.clear();

		String index = configManager.getConfiguration(CONFIG_GROUP, KEY_INDEX);
		if (index == null || index.isEmpty())
		{
			return;
		}

		List<String> keys;
		try
		{
			keys = gson.fromJson(index, new TypeToken<List<String>>()
			{
			}.getType());
		}
		catch (Exception e)
		{
			log.warn("Could not read account index, starting empty", e);
			return;
		}

		if (keys == null)
		{
			return;
		}

		for (String key : keys)
		{
			String blob = configManager.getConfiguration(CONFIG_GROUP, KEY_ACCOUNT_PREFIX + key);
			if (blob == null || blob.isEmpty())
			{
				continue;
			}

			try
			{
				AccountStats stats = decode(blob);
				stats.ensureInitialised();
				accounts.put(key, stats);
			}
			catch (Exception e)
			{
				log.warn("Could not read stats for account {}, skipping", key, e);
			}
		}
	}

	/**
	 * Persists any account touched since the last flush. Also refreshes best-day records and
	 * prunes, both of which are cheap here and would be wasteful per tick.
	 */
	public void flush(LocalDate today)
	{
		if (dirty.isEmpty())
		{
			return;
		}

		for (String key : new ArrayList<>(dirty))
		{
			AccountStats stats = accounts.get(key);
			if (stats == null)
			{
				continue;
			}

			stats.refreshRecords(today);
			stats.prune(today);

			try
			{
				String blob = encode(stats);
				if (blob.length() > SIZE_WARN_BYTES)
				{
					log.warn("Stats blob for {} is {} bytes, which is large for a synced config value",
						stats.getName(), blob.length());
				}
				configManager.setConfiguration(CONFIG_GROUP, KEY_ACCOUNT_PREFIX + key, blob);
			}
			catch (IOException e)
			{
				log.warn("Could not save stats for account {}", key, e);
			}
		}

		configManager.setConfiguration(CONFIG_GROUP, KEY_INDEX, gson.toJson(new ArrayList<>(accounts.keySet())));
		dirty.clear();
	}

	public void markDirty()
	{
		if (activeAccountKey != null)
		{
			dirty.add(activeAccountKey);
		}
	}

	/** Wipes one account, or everything when accountKey is null. */
	public void reset(String accountKey)
	{
		if (accountKey == null)
		{
			for (String key : accounts.keySet())
			{
				configManager.unsetConfiguration(CONFIG_GROUP, KEY_ACCOUNT_PREFIX + key);
			}
			accounts.clear();
			dirty.clear();
			configManager.unsetConfiguration(CONFIG_GROUP, KEY_INDEX);
			activeAccountKey = null;
			return;
		}

		accounts.remove(accountKey);
		dirty.remove(accountKey);
		configManager.unsetConfiguration(CONFIG_GROUP, KEY_ACCOUNT_PREFIX + accountKey);
		configManager.setConfiguration(CONFIG_GROUP, KEY_INDEX, gson.toJson(new ArrayList<>(accounts.keySet())));

		if (accountKey.equals(activeAccountKey))
		{
			activeAccountKey = null;
		}
	}

	/**
	 * Clears just the given stats, for one account or all of them. Backs the per-category reset,
	 * which must not disturb the categories either side of it.
	 */
	public void resetStats(String accountKey, Collection<String> statIds, LocalDate today)
	{
		if (statIds.isEmpty())
		{
			return;
		}

		for (Map.Entry<String, AccountStats> entry : accounts.entrySet())
		{
			if (accountKey != null && !accountKey.equals(entry.getKey()))
			{
				continue;
			}

			entry.getValue().removeStats(statIds);
			dirty.add(entry.getKey());
		}

		flush(today);
	}

	/** Raw JSON for one account, or all of them, for the export button. */
	public String exportJson(String accountKey)
	{
		if (accountKey != null)
		{
			AccountStats stats = accounts.get(accountKey);
			return stats == null ? "{}" : gson.toJson(stats);
		}
		return gson.toJson(accounts);
	}

	private String encode(AccountStats stats) throws IOException
	{
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (Writer writer = new OutputStreamWriter(new GZIPOutputStream(bytes), StandardCharsets.UTF_8))
		{
			gson.toJson(stats, writer);
		}
		return Base64.getEncoder().encodeToString(bytes.toByteArray());
	}

	private AccountStats decode(String blob) throws IOException
	{
		byte[] compressed = Base64.getDecoder().decode(blob);
		try (Reader reader = new InputStreamReader(new GZIPInputStream(new ByteArrayInputStream(compressed)), StandardCharsets.UTF_8))
		{
			return gson.fromJson(reader, AccountStats.class);
		}
	}
}

package com.woodycode23.lifetracker.stats;

import java.text.NumberFormat;
import java.util.Locale;

/**
 * How a raw counter is rendered. Every stat is stored as a plain long; the unit decides
 * what that long means when it reaches the panel.
 */
public enum StatUnit
{
	/** A plain tally: sips, kills, deaths, logins. */
	COUNT,
	/** Map squares. Rendered as a count, but {@link com.woodycode23.lifetracker.Comparisons} can turn it into distance. */
	TILES,
	/** Game ticks (600ms each). Rendered as a duration. */
	TICKS,
	/** Hitpoints healed or damage dealt/taken. */
	HITPOINTS,
	/** Food energy, derived from how much a consumable heals. */
	CALORIES;

	private static final NumberFormat NUMBER = NumberFormat.getIntegerInstance(Locale.US);

	public String format(long value)
	{
		if (this == TICKS)
		{
			return formatDuration(value);
		}
		if (this == CALORIES)
		{
			return NUMBER.format(value) + " kcal";
		}
		return NUMBER.format(value);
	}

	/**
	 * Ticks to a compact human duration. Anything under a minute stays in seconds so that
	 * short prayer flicks do not all collapse to "0m".
	 */
	public static String formatDuration(long ticks)
	{
		long totalSeconds = (ticks * 600L) / 1000L;

		if (totalSeconds < 60)
		{
			return totalSeconds + "s";
		}

		long hours = totalSeconds / 3600;
		long minutes = (totalSeconds % 3600) / 60;

		if (hours == 0)
		{
			return minutes + "m";
		}

		long days = hours / 24;
		if (days > 0)
		{
			return days + "d " + (hours % 24) + "h";
		}

		return hours + "h " + minutes + "m";
	}

	public static String formatNumber(long value)
	{
		return NUMBER.format(value);
	}
}

package com.woodycode23.lifetracker.stats;

/**
 * Storage keys for every fixed stat, plus the prefixes used by dynamically discovered ones.
 *
 * <p>These strings are the on-disk format. Renaming one silently orphans that stat's saved
 * history, so change the display name in {@link #registerFixed} instead.
 */
public final class Stats
{
	public static final String POTION_PREFIX = "pot.";
	public static final String FOOD_PREFIX = "food.";
	public static final String PRAYER_PREFIX = "prayon.";

	// Movement
	public static final String TILES_TOTAL = "move.tiles.total";
	public static final String TILES_WALKED = "move.tiles.walked";
	public static final String TILES_RAN = "move.tiles.ran";
	public static final String TILES_SAILED = "move.tiles.sailed";
	public static final String TILES_OTHER = "move.tiles.other";
	public static final String TELEPORTS = "move.teleports";

	// Consumables
	public static final String CALORIES = "con.calories";
	public static final String POTION_DOSES = "con.potion.doses";
	public static final String FOOD_EATEN = "con.food.eaten";
	public static final String FOOD_HEALED = "con.food.healed";

	// Prayer
	public static final String PRAYER_OVERHEAD_UPTIME = "pray.overhead.any";
	public static final String PRAYER_ANY_UPTIME = "pray.any";
	public static final String PRAYER_POINTS_DRAINED = "pray.points.drained";

	// Session
	public static final String PLAYTIME = "ses.playtime";
	public static final String ACTIVE_TIME = "ses.active";
	public static final String IDLE_TIME = "ses.idle";
	public static final String LOGINS = "ses.logins";

	// Combat and economy
	public static final String DAMAGE_DEALT = "cmb.damage.dealt";
	public static final String DAMAGE_TAKEN = "cmb.damage.taken";
	public static final String DEATHS = "cmb.deaths";
	public static final String NPC_KILLS = "cmb.kills";
	public static final String SPECS_USED = "cmb.spec";
	public static final String HIGH_ALCHS = "cmb.alch.high";
	public static final String LOW_ALCHS = "cmb.alch.low";

	static void registerFixed(StatCatalog c)
	{
		c.register(TILES_TOTAL, "Tiles moved", StatCategory.MOVEMENT, StatUnit.TILES, 0, true);
		c.register(TILES_WALKED, "Tiles walked", StatCategory.MOVEMENT, StatUnit.TILES, 1, true);
		c.register(TILES_RAN, "Tiles ran", StatCategory.MOVEMENT, StatUnit.TILES, 2, true);
		c.register(TILES_SAILED, "Tiles sailed", StatCategory.MOVEMENT, StatUnit.TILES, 3, true);
		c.register(TILES_OTHER, "Tiles moved (unclassified)", StatCategory.MOVEMENT, StatUnit.TILES, 4, false);
		c.register(TELEPORTS, "Teleports", StatCategory.MOVEMENT, StatUnit.COUNT, 5, false);

		// Calories lead the consumables card, the way a nutrition summary leads with them.
		c.register(CALORIES, "Calories consumed", StatCategory.CONSUMABLES, StatUnit.CALORIES, 0, true);
		c.register(POTION_DOSES, "Potion doses sipped", StatCategory.CONSUMABLES, StatUnit.COUNT, 1, true);
		c.register(FOOD_EATEN, "Food eaten", StatCategory.CONSUMABLES, StatUnit.COUNT, 2, true);
		c.register(FOOD_HEALED, "Hitpoints healed", StatCategory.CONSUMABLES, StatUnit.HITPOINTS, 3, false);

		c.register(PRAYER_OVERHEAD_UPTIME, "Overhead prayer uptime", StatCategory.PRAYER, StatUnit.TICKS, 0, true);
		c.register(PRAYER_ANY_UPTIME, "Any prayer uptime", StatCategory.PRAYER, StatUnit.TICKS, 1, false);
		c.register(PRAYER_POINTS_DRAINED, "Prayer points drained", StatCategory.PRAYER, StatUnit.COUNT, 2, true);

		c.register(PLAYTIME, "Time played", StatCategory.SESSION, StatUnit.TICKS, 0, true);
		c.register(ACTIVE_TIME, "Active time", StatCategory.SESSION, StatUnit.TICKS, 1, false);
		c.register(IDLE_TIME, "Idle time", StatCategory.SESSION, StatUnit.TICKS, 2, false);
		c.register(LOGINS, "Logins", StatCategory.SESSION, StatUnit.COUNT, 3, false);

		c.register(DAMAGE_DEALT, "Damage dealt", StatCategory.COMBAT, StatUnit.HITPOINTS, 0, true);
		c.register(DAMAGE_TAKEN, "Damage taken", StatCategory.COMBAT, StatUnit.HITPOINTS, 1, false);
		c.register(DEATHS, "Deaths", StatCategory.COMBAT, StatUnit.COUNT, 2, true);
		c.register(NPC_KILLS, "NPC kills", StatCategory.COMBAT, StatUnit.COUNT, 3, true);
		c.register(SPECS_USED, "Special attacks used", StatCategory.COMBAT, StatUnit.COUNT, 4, false);
		c.register(HIGH_ALCHS, "High alchemy casts", StatCategory.COMBAT, StatUnit.COUNT, 5, false);
		c.register(LOW_ALCHS, "Low alchemy casts", StatCategory.COMBAT, StatUnit.COUNT, 6, false);
	}

	private Stats()
	{
	}
}

package com.woodycode23.lifetracker.trackers;

import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.eventbus.Subscribe;
import com.woodycode23.lifetracker.stats.StatCategory;
import com.woodycode23.lifetracker.stats.Stats;

/**
 * Damage, deaths, kills, special attacks and alchemy.
 *
 * <p>Damage dealt uses the client's own "this hitsplat is mine" flag, so hits landed by other
 * players on the same target are not stolen. Kills are attributed only when the dying NPC and
 * the player were engaged with each other, which is the closest an external plugin can get to
 * the game's own kill credit.
 */
public class CombatTracker implements Tracker
{
	private final Client client;
	private final TrackerContext ctx;

	private int lastSpecialAttackEnergy = -1;

	@Inject
	public CombatTracker(Client client, TrackerContext ctx)
	{
		this.client = client;
		this.ctx = ctx;
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!ctx.enabled(StatCategory.COMBAT) || !ctx.hasActiveAccount())
		{
			return;
		}

		Hitsplat hitsplat = event.getHitsplat();
		int amount = hitsplat.getAmount();
		if (amount <= 0)
		{
			return;
		}

		Player local = client.getLocalPlayer();
		if (event.getActor() == local)
		{
			ctx.add(Stats.DAMAGE_TAKEN, amount);
		}
		else if (hitsplat.isMine())
		{
			ctx.add(Stats.DAMAGE_DEALT, amount);
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!ctx.enabled(StatCategory.COMBAT) || !ctx.hasActiveAccount())
		{
			return;
		}

		Actor actor = event.getActor();
		Player local = client.getLocalPlayer();

		if (actor == local)
		{
			ctx.add(Stats.DEATHS, 1);
			return;
		}

		if (actor instanceof NPC && (actor.getInteracting() == local || (local != null && local.getInteracting() == actor)))
		{
			ctx.add(Stats.NPC_KILLS, 1);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() != VarPlayerID.SA_ENERGY)
		{
			return;
		}

		int current = event.getValue();
		int previous = lastSpecialAttackEnergy;
		lastSpecialAttackEnergy = current;

		if (!ctx.enabled(StatCategory.COMBAT) || !ctx.hasActiveAccount())
		{
			return;
		}

		// Energy only falls when a special is used; it regenerates upward in ticks.
		if (previous > current)
		{
			ctx.add(Stats.SPECS_USED, 1);
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() != client.getLocalPlayer())
		{
			return;
		}

		if (!ctx.enabled(StatCategory.COMBAT) || !ctx.hasActiveAccount())
		{
			return;
		}

		int animation = event.getActor().getAnimation();
		if (animation == AnimationID.HUMAN_CASTHIGHLVLALCHEMY)
		{
			ctx.add(Stats.HIGH_ALCHS, 1);
		}
		else if (animation == AnimationID.HUMAN_CASTLOWLVLALCHEMY)
		{
			ctx.add(Stats.LOW_ALCHS, 1);
		}
	}

	@Override
	public void reset()
	{
		lastSpecialAttackEnergy = -1;
	}
}

package com.woodycode23.lifetracker.trackers;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.itemstats.Effect;
import net.runelite.client.plugins.itemstats.ItemStatChanges;
import net.runelite.client.plugins.itemstats.StatChange;
import com.woodycode23.lifetracker.Calories;
import com.woodycode23.lifetracker.stats.StatCategory;
import com.woodycode23.lifetracker.stats.Stats;

/**
 * Counts potion doses, food eaten and hitpoints healed.
 *
 * <p>This class does the RuneLite half: turning events into inventory snapshots and applying
 * whatever {@link ConsumeDetector} works out. All of the pairing and diffing rules live in that
 * class, which has no client dependencies and is directly tested.
 *
 * <p>Potions are identified by item name rather than an item id table. Anything ending in a dose
 * suffix is a potion and the text in front of it is the family, so a potion added to the game
 * after this was written is tracked correctly with no update.
 */
@Slf4j
public class ConsumableTracker implements Tracker
{
	/** Shared by eating and drinking, which is why one gate covers both. */
	private static final int CONSUME_ANIMATION = AnimationID.HUMAN_EAT;

	/** How far apart the animation and the inventory update may land and still be one consume. */
	private static final int CONSUME_WINDOW_TICKS = 1;

	private static final Pattern DOSE_SUFFIX = Pattern.compile("^(.*?)\\((\\d)\\)$");

	private final Client client;
	private final ItemManager itemManager;
	private final ItemStatChanges itemStats;
	private final TrackerContext ctx;
	private final ConsumeDetector detector;

	private int lastHitpoints = -1;
	private int lastConsumeTick = Integer.MIN_VALUE;

	/** Item id to potion details, or null for known non-potions. Item names never change at runtime. */
	private final Map<Integer, ConsumeDetector.PotionInfo> potionCache = new HashMap<>();

	@Inject
	public ConsumableTracker(Client client, ItemManager itemManager, ItemStatChanges itemStats, TrackerContext ctx)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.itemStats = itemStats;
		this.ctx = ctx;
		this.detector = new ConsumeDetector(this::potionInfo, this::isConsumable, CONSUME_WINDOW_TICKS);
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() != client.getLocalPlayer() || event.getActor().getAnimation() != CONSUME_ANIMATION)
		{
			return;
		}

		int tick = client.getTickCount();
		lastConsumeTick = tick;

		log.debug("consume animation at tick {}", tick);
		apply(detector.onAnimation(tick));
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		apply(detector.onInventory(client.getTickCount(), countItems(event.getItemContainer())));
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.HITPOINTS)
		{
			return;
		}

		int current = event.getBoostedLevel();
		int previous = lastHitpoints;
		lastHitpoints = current;

		if (previous < 0 || current <= previous || !enabled())
		{
			return;
		}

		// Only healing that follows a consume counts; natural regeneration is not a stat here.
		if (Math.abs(client.getTickCount() - lastConsumeTick) <= CONSUME_WINDOW_TICKS)
		{
			ctx.add(Stats.FOOD_HEALED, current - previous);
		}
	}

	private void apply(ConsumeDetector.Result result)
	{
		if (result.isEmpty() || !enabled())
		{
			return;
		}

		for (Map.Entry<String, Integer> entry : result.potionDoses.entrySet())
		{
			log.debug("counted {} dose(s) of {}", entry.getValue(), entry.getKey());
			ctx.add(ctx.catalog().registerPotion(entry.getKey()), entry.getValue());
		}

		if (result.totalDoses > 0)
		{
			ctx.add(Stats.POTION_DOSES, result.totalDoses);
		}

		if (result.foodEaten > 0)
		{
			log.debug("counted {} food eaten", result.foodEaten);
			ctx.add(Stats.FOOD_EATEN, result.foodEaten);
		}

		// Individual foods are registered by item name the first time one is eaten, the same way
		// potion families are, so the panel can list them without a hardcoded food table.
		for (Map.Entry<Integer, Integer> entry : result.consumedItems.entrySet())
		{
			if (potionInfo(entry.getKey()) != null)
			{
				continue;
			}

			String name = itemName(entry.getKey());
			if (name != null)
			{
				ctx.add(ctx.catalog().registerFood(name), entry.getValue());
			}
		}

		long calories = calories(result.consumedItems)
			+ Calories.fromDoses(result.totalDoses, ctx.kcalPerPotionDose());
		if (calories > 0)
		{
			ctx.add(Stats.CALORIES, calories);
		}
	}

	/**
	 * Calories from what the game says a food is worth.
	 *
	 * <p>OSRS has no nutrition data, so this is one documented rule rather than a table of made up
	 * per item figures: calories are the hitpoints an item restores, times a configurable factor.
	 * That covers every food in the game, including ones added after this was written.
	 *
	 * <p>The default factor of 10 is not arbitrary. It happens to put the staples within roughly a
	 * tenth of the real world calorie count for the same fish: shark 200, manta ray 220, karambwan
	 * 180, lobster 120. A derived rule that lands on the real numbers beats a hand written table
	 * that has to be maintained.
	 *
	 * <p>The theoretical heal is used rather than the actual one, so a shark eaten at full health
	 * still counts as a shark. Items that damage you, such as the divine potions, contribute
	 * nothing rather than negative calories.
	 *
	 * <p>Doses are charged separately by the caller, because most potions restore no hitpoints and
	 * would otherwise be free.
	 */
	private long calories(Map<Integer, Integer> consumedItems)
	{
		long total = 0;
		for (Map.Entry<Integer, Integer> entry : consumedItems.entrySet())
		{
			total += Calories.fromHealing(hitpointsRestoredBy(entry.getKey()), entry.getValue(), ctx.kcalPerHitpoint());
		}
		return total;
	}

	private int hitpointsRestoredBy(int itemId)
	{
		try
		{
			Effect effect = itemStats.get(itemId);
			if (effect == null)
			{
				return 0;
			}

			for (StatChange change : effect.calculate(client).getStatChanges())
			{
				// Fully qualified: the item stats package also has a class called Stats.
				if (change.getStat() == net.runelite.client.plugins.itemstats.stats.Stats.HITPOINTS)
				{
					return change.getTheoretical();
				}
			}
		}
		catch (Exception e)
		{
			// An item the stats service does not know is simply worth nothing.
			log.debug("no stat changes for item {}", itemId, e);
		}
		return 0;
	}

	private boolean enabled()
	{
		return ctx.enabled(StatCategory.CONSUMABLES) && ctx.hasActiveAccount();
	}

	/** Whether the client's own consumable table has an effect for this item. */
	private boolean isConsumable(int itemId)
	{
		try
		{
			return itemStats.get(itemId) != null;
		}
		catch (Exception e)
		{
			log.debug("no stat changes for item {}", itemId, e);
			return false;
		}
	}

	private String itemName(int itemId)
	{
		try
		{
			ItemComposition composition = itemManager.getItemComposition(itemId);
			if (composition != null && composition.getName() != null && !composition.getName().isEmpty())
			{
				return composition.getName();
			}
		}
		catch (Exception e)
		{
			log.debug("no composition for item {}", itemId, e);
		}
		return null;
	}

	private ConsumeDetector.PotionInfo potionInfo(int itemId)
	{
		if (potionCache.containsKey(itemId))
		{
			return potionCache.get(itemId);
		}

		ConsumeDetector.PotionInfo info = null;
		try
		{
			// A dose suffix alone is not enough: "Watering can(7)" matches it and was logged as
			// seven doses drunk. The item must also be something the game lets you consume.
			ItemComposition composition = isConsumable(itemId) ? itemManager.getItemComposition(itemId) : null;
			// Noted potions cannot be drunk, and their name is identical to the real item.
			if (composition != null && composition.getNote() == -1)
			{
				Matcher matcher = DOSE_SUFFIX.matcher(composition.getName());
				if (matcher.matches())
				{
					info = new ConsumeDetector.PotionInfo(matcher.group(1).trim(), Integer.parseInt(matcher.group(2)));
				}
			}
		}
		catch (Exception e)
		{
			// An unknown item id is simply not a potion as far as this tracker is concerned.
			info = null;
		}

		potionCache.put(itemId, info);
		return info;
	}

	private static Map<Integer, Integer> countItems(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}

		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				counts.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return counts;
	}

	@Override
	public void reset()
	{
		detector.reset();
		potionCache.clear();
		lastHitpoints = -1;
		lastConsumeTick = Integer.MIN_VALUE;
	}
}

package com.woodycode23.lifetracker.trackers;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntPredicate;

/**
 * Decides what was consumed, from inventory snapshots paired with the eat/drink animation.
 *
 * <p>Deliberately free of any RuneLite type so the pairing rules can be tested directly.
 *
 * <p>The pairing is order independent, which is the whole reason this class exists. An earlier
 * version only inspected an inventory change if the animation had <em>already</em> been seen, so
 * whenever the client posted the inventory update first, the sip was silently discarded. Both
 * events now feed the same window and either one can complete the pair:
 *
 * <ul>
 *   <li>animation first, inventory second: the inventory change applies immediately</li>
 *   <li>inventory first, animation second: the diff is held and applied when the animation lands</li>
 *   <li>inventory with no animation at all: dropped, which is what keeps banking and looting out</li>
 * </ul>
 */
public class ConsumeDetector
{
	/** A potion family and how many doses one of that item holds. */
	public static final class PotionInfo
	{
		public final String family;
		public final int doses;

		public PotionInfo(String family, int doses)
		{
			this.family = family;
			this.doses = doses;
		}
	}

	/** Resolves an item id to potion details, or null when the item is not a potion. */
	public interface PotionLookup
	{
		PotionInfo lookup(int itemId);
	}

	/** What a completed pair worked out to. Empty when nothing was consumed. */
	public static final class Result
	{
		public final Map<String, Integer> potionDoses = new LinkedHashMap<>();

		/**
		 * The actual items that left the inventory, so a caller can ask the game what each one
		 * was worth. Needed for calories, which depend on the specific item rather than on the
		 * family or the tally.
		 */
		public final Map<Integer, Integer> consumedItems = new LinkedHashMap<>();

		public int totalDoses;
		public int foodEaten;

		public boolean isEmpty()
		{
			return totalDoses == 0 && foodEaten == 0;
		}

		void merge(Result other)
		{
			for (Map.Entry<String, Integer> entry : other.potionDoses.entrySet())
			{
				potionDoses.merge(entry.getKey(), entry.getValue(), Integer::sum);
			}
			for (Map.Entry<Integer, Integer> entry : other.consumedItems.entrySet())
			{
				consumedItems.merge(entry.getKey(), entry.getValue(), Integer::sum);
			}
			totalDoses += other.totalDoses;
			foodEaten += other.foodEaten;
		}
	}

	private static final class Pending
	{
		final int tick;
		final Map<Integer, Integer> before;
		final Map<Integer, Integer> after;

		Pending(int tick, Map<Integer, Integer> before, Map<Integer, Integer> after)
		{
			this.tick = tick;
			this.before = before;
			this.after = after;
		}
	}

	private final PotionLookup lookup;

	/** Whether the game considers this item something you can eat or drink at all. */
	private final IntPredicate isConsumable;
	private final int windowTicks;

	private Map<Integer, Integer> previousInventory;
	private int animationTick = Integer.MIN_VALUE;

	/** Inventory diffs still waiting for an animation to justify them. */
	private final Deque<Pending> pending = new ArrayDeque<>();

	public ConsumeDetector(PotionLookup lookup, IntPredicate isConsumable, int windowTicks)
	{
		this.lookup = lookup;
		this.isConsumable = isConsumable;
		this.windowTicks = windowTicks;
	}

	/**
	 * Records the eat/drink animation. Returns anything that was already waiting on it, which is
	 * the case whenever the client posts the inventory update first.
	 */
	public Result onAnimation(int tick)
	{
		animationTick = tick;

		Result result = new Result();
		Iterator<Pending> it = pending.iterator();
		while (it.hasNext())
		{
			Pending candidate = it.next();
			if (withinWindow(tick, candidate.tick))
			{
				result.merge(diff(candidate.before, candidate.after));
				it.remove();
			}
			else if (candidate.tick < tick - windowTicks)
			{
				it.remove();
			}
		}
		return result;
	}

	/**
	 * Records an inventory snapshot. Returns the consumption immediately when the animation has
	 * already been seen, otherwise holds the diff until it is.
	 */
	public Result onInventory(int tick, Map<Integer, Integer> current)
	{
		Map<Integer, Integer> before = previousInventory;
		previousInventory = new HashMap<>(current);

		// The first snapshot after login or a reset is a baseline, not a change.
		if (before == null)
		{
			return new Result();
		}

		if (withinWindow(tick, animationTick))
		{
			return diff(before, previousInventory);
		}

		dropExpired(tick);
		pending.addLast(new Pending(tick, before, new HashMap<>(current)));
		return new Result();
	}

	private void dropExpired(int tick)
	{
		while (!pending.isEmpty() && pending.peekFirst().tick < tick - windowTicks)
		{
			pending.removeFirst();
		}
	}

	private boolean withinWindow(int tick, int other)
	{
		return other != Integer.MIN_VALUE && Math.abs(tick - other) <= windowTicks;
	}

	/**
	 * Potions are compared as total doses per family, so a 4-dose becoming a 3-dose reads as one
	 * sip and finishing a potion into an empty vial reads as one more. Food is an item the game
	 * treats as consumable that left the inventory singly; foods leaving a container behind still
	 * net to one, because only decreases count.
	 */
	private Result diff(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		Result result = new Result();

		Map<String, Integer> dosesBefore = doseTotals(before);
		Map<String, Integer> dosesAfter = doseTotals(after);

		for (Map.Entry<String, Integer> entry : dosesBefore.entrySet())
		{
			int consumed = entry.getValue() - dosesAfter.getOrDefault(entry.getKey(), 0);
			if (consumed > 0)
			{
				result.potionDoses.merge(entry.getKey(), consumed, Integer::sum);
				result.totalDoses += consumed;
			}
		}

		for (Map.Entry<Integer, Integer> entry : before.entrySet())
		{
			int lost = entry.getValue() - after.getOrDefault(entry.getKey(), 0);
			if (lost <= 0)
			{
				continue;
			}

			if (lookup.lookup(entry.getKey()) != null)
			{
				// A potion item leaving is one dose drunk, whatever the dose count was.
				result.consumedItems.merge(entry.getKey(), lost, Integer::sum);
				continue;
			}

			// Ask the game whether this is edible rather than inferring it from "not a potion".
			// Equipping gear also removes an item from the inventory, and by elimination that read
			// as a meal: captured data logged Tumeken's shadow and Dharok's platebody as food.
			if (!isConsumable.test(entry.getKey()))
			{
				continue;
			}

			// Exactly one, not any decrease. Food is never eaten several at a time, so a stack
			// that fell by more than one is something else happening to coincide with the bite.
			if (lost == 1)
			{
				result.foodEaten++;
				result.consumedItems.merge(entry.getKey(), 1, Integer::sum);
			}
		}

		return result;
	}

	private Map<String, Integer> doseTotals(Map<Integer, Integer> inventory)
	{
		Map<String, Integer> totals = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : inventory.entrySet())
		{
			PotionInfo info = lookup.lookup(entry.getKey());
			if (info != null)
			{
				totals.merge(info.family, info.doses * entry.getValue(), Integer::sum);
			}
		}
		return totals;
	}

	public void reset()
	{
		previousInventory = null;
		animationTick = Integer.MIN_VALUE;
		pending.clear();
	}
}

package com.woodycode23.lifetracker.trackers;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import com.woodycode23.lifetracker.stats.StatCategory;
import com.woodycode23.lifetracker.stats.Stats;

/**
 * Turns position samples into tiles walked, ran and sailed.
 *
 * <p>On foot the classification is exact rather than heuristic: a player covers one tile per
 * tick walking and two running, so the per-tick distance <em>is</em> the answer and there is no
 * need to consult the run varbit or worry about run energy draining mid-journey.
 *
 * <p>Sailing is read from the world view rather than from any sailing-specific varbit. A player
 * aboard a vessel occupies the vessel's own non-top-level world view, whose base coordinates
 * shift each tick as the ship moves. Distance sailed is therefore the movement of that base,
 * while walking around on deck stays visible as ordinary scene-local movement. A static
 * instance also has a non-top-level world view, but its base never moves, so it contributes
 * nothing and needs no special case.
 */
public class MovementTracker implements Tracker
{
	/** Two tiles per tick is a run; anything more on foot is not locomotion. */
	private static final int RUN_DISTANCE = 2;

	/**
	 * Jumps this large are teleports rather than travel. Below it, a large jump is more likely
	 * a dropped tick or a forced move, which is counted as distance but left unclassified.
	 */
	private static final int TELEPORT_DISTANCE = 13;

	/** A vessel moving faster than this in one tick is a reposition, not sailing. */
	private static final int MAX_VESSEL_DISTANCE = 8;

	private static final int UNSET = Integer.MIN_VALUE;

	private final Client client;
	private final TrackerContext ctx;

	private WorldPoint lastWorldPoint;

	private int lastWorldViewId = -1;
	private int lastBaseX = UNSET;
	private int lastBaseY = UNSET;
	private int lastSceneX = UNSET;
	private int lastSceneY = UNSET;

	@Inject
	public MovementTracker(Client client, TrackerContext ctx)
	{
		this.client = client;
		this.ctx = ctx;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!ctx.enabled(StatCategory.MOVEMENT) || !ctx.hasActiveAccount())
		{
			return;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			reset();
			return;
		}

		WorldView worldView = player.getWorldView();
		boolean topLevel = worldView == null || worldView.isTopLevel();

		// Any change of world view (boarding, disembarking, entering an instance) breaks
		// positional continuity, so start fresh rather than diff across the seam.
		int worldViewId = worldView == null ? -1 : worldView.getId();
		if (worldViewId != lastWorldViewId)
		{
			resetPositions();
			lastWorldViewId = worldViewId;
		}

		if (topLevel)
		{
			trackOnFootTopLevel(player);
		}
		else
		{
			trackVessel(worldView);
			trackOnFootInWorldView(player);
		}
	}

	/**
	 * On the main world view, world coordinates are stable across scene reloads, so they are
	 * the safest thing to diff.
	 */
	private void trackOnFootTopLevel(Player player)
	{
		WorldPoint now = player.getWorldLocation();
		if (now == null)
		{
			lastWorldPoint = null;
			return;
		}

		WorldPoint previous = lastWorldPoint;
		lastWorldPoint = now;

		if (previous == null)
		{
			return;
		}

		if (previous.getPlane() != now.getPlane())
		{
			ctx.add(Stats.TELEPORTS, 1);
			return;
		}

		record(distance(previous.getX(), previous.getY(), now.getX(), now.getY()));
	}

	/**
	 * Inside a vessel's world view, world coordinates move with the ship. Scene coordinates are
	 * relative to that world view, so they isolate the player's own movement on the deck.
	 */
	private void trackOnFootInWorldView(Player player)
	{
		LocalPoint local = player.getLocalLocation();
		if (local == null)
		{
			lastSceneX = UNSET;
			lastSceneY = UNSET;
			return;
		}

		int sceneX = local.getSceneX();
		int sceneY = local.getSceneY();
		int previousX = lastSceneX;
		int previousY = lastSceneY;

		lastSceneX = sceneX;
		lastSceneY = sceneY;
		lastWorldPoint = null;

		if (previousX == UNSET)
		{
			return;
		}

		int distance = distance(previousX, previousY, sceneX, sceneY);
		if (distance <= RUN_DISTANCE)
		{
			record(distance);
		}
		// Larger deck jumps come from the vessel's scene shifting under the player, which is
		// already accounted for as sailing.
	}

	private void trackVessel(WorldView worldView)
	{
		int baseX = worldView.getBaseX();
		int baseY = worldView.getBaseY();
		int previousX = lastBaseX;
		int previousY = lastBaseY;

		lastBaseX = baseX;
		lastBaseY = baseY;

		if (previousX == UNSET)
		{
			return;
		}

		int distance = distance(previousX, previousY, baseX, baseY);
		if (distance > 0 && distance <= MAX_VESSEL_DISTANCE)
		{
			ctx.add(Stats.TILES_SAILED, distance);
			ctx.add(Stats.TILES_TOTAL, distance);
		}
	}

	private void record(int distance)
	{
		if (distance <= 0)
		{
			return;
		}

		if (distance >= TELEPORT_DISTANCE)
		{
			ctx.add(Stats.TELEPORTS, 1);
			return;
		}

		if (distance == 1)
		{
			ctx.add(Stats.TILES_WALKED, 1);
		}
		else if (distance == RUN_DISTANCE)
		{
			ctx.add(Stats.TILES_RAN, RUN_DISTANCE);
		}
		else
		{
			ctx.add(Stats.TILES_OTHER, distance);
		}

		ctx.add(Stats.TILES_TOTAL, distance);
	}

	/** Chebyshev distance: a diagonal step is one tile of travel, exactly as the game moves you. */
	private static int distance(int fromX, int fromY, int toX, int toY)
	{
		return Math.max(Math.abs(toX - fromX), Math.abs(toY - fromY));
	}

	private void resetPositions()
	{
		lastWorldPoint = null;
		lastBaseX = UNSET;
		lastBaseY = UNSET;
		lastSceneX = UNSET;
		lastSceneY = UNSET;
	}

	@Override
	public void reset()
	{
		resetPositions();
		lastWorldViewId = -1;
	}
}

package com.woodycode23.lifetracker.trackers;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import com.woodycode23.lifetracker.stats.StatCategory;
import com.woodycode23.lifetracker.stats.Stats;

/**
 * Samples active prayers once per tick to build uptime, and watches the prayer level for drain.
 *
 * <p>Uptime is measured in ticks because that is the resolution the game actually has. A
 * one-tick flick and a ten minute grind are the same measurement at different scales.
 *
 * <p>Prayers are registered with the catalog on first use, so the panel only ever lists prayers
 * you have actually turned on, and prayers added to the game later need no code change.
 */
public class PrayerTracker implements Tracker
{
	/**
	 * Prayers that put an icon above your head. Matched by enum name rather than by constant so
	 * that a client version which renames or removes one of these degrades to "not an overhead"
	 * instead of failing to compile.
	 *
	 * <p>This is the six classic overheads plus the three Ruinous protection equivalents. Other
	 * Ruinous prayers are still tracked individually, just not counted toward overhead uptime.
	 */
	private static final Set<String> OVERHEAD_NAMES = new HashSet<>(Arrays.asList(
		"PROTECT_FROM_MAGIC",
		"PROTECT_FROM_MISSILES",
		"PROTECT_FROM_MELEE",
		"RETRIBUTION",
		"REDEMPTION",
		"SMITE",
		"RP_DAMPEN_MAGIC",
		"RP_DAMPEN_RANGED",
		"RP_DAMPEN_MELEE"
	));

	/** Short joining words stay lowercase when a prayer name is prettified. */
	private static final Set<String> LOWERCASE_WORDS = new HashSet<>(Arrays.asList("from", "of", "the"));

	private final Client client;
	private final TrackerContext ctx;

	private int lastPrayerPoints = -1;

	@Inject
	public PrayerTracker(Client client, TrackerContext ctx)
	{
		this.client = client;
		this.ctx = ctx;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!ctx.enabled(StatCategory.PRAYER) || !ctx.hasActiveAccount())
		{
			return;
		}

		boolean anyActive = false;
		boolean anyOverhead = false;

		for (Prayer prayer : Prayer.values())
		{
			// Read the prayer's own varbit rather than Client#isPrayerActive, which is
			// deprecated for mishandling the Deadeye and Mystic Vigour pairs.
			if (client.getVarbitValue(prayer.getVarbit()) == 0)
			{
				continue;
			}

			boolean overhead = OVERHEAD_NAMES.contains(prayer.name());
			ctx.add(ctx.catalog().registerPrayer(displayName(prayer), overhead), 1);

			anyActive = true;
			anyOverhead |= overhead;
		}

		if (anyActive)
		{
			ctx.add(Stats.PRAYER_ANY_UPTIME, 1);
		}
		if (anyOverhead)
		{
			ctx.add(Stats.PRAYER_OVERHEAD_UPTIME, 1);
		}

		trackDrain();
	}

	/** Only decreases count, so restoring prayer never shows up as having spent it. */
	private void trackDrain()
	{
		int current = client.getBoostedSkillLevel(Skill.PRAYER);
		int previous = lastPrayerPoints;
		lastPrayerPoints = current;

		if (previous > current)
		{
			ctx.add(Stats.PRAYER_POINTS_DRAINED, previous - current);
		}
	}

	static String displayName(Prayer prayer)
	{
		String raw = prayer.name();
		if (raw.startsWith("RP_"))
		{
			raw = raw.substring(3);
		}

		String[] words = raw.toLowerCase(Locale.US).split("_");
		StringBuilder out = new StringBuilder();

		for (int i = 0; i < words.length; i++)
		{
			String word = words[i];
			if (word.isEmpty())
			{
				continue;
			}

			if (out.length() > 0)
			{
				out.append(' ');
			}

			if (i > 0 && LOWERCASE_WORDS.contains(word))
			{
				out.append(word);
			}
			else
			{
				out.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
			}
		}

		return out.toString();
	}

	@Override
	public void reset()
	{
		lastPrayerPoints = -1;
	}
}

package com.woodycode23.lifetracker.trackers;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import com.woodycode23.lifetracker.stats.StatCategory;
import com.woodycode23.lifetracker.stats.Stats;

/**
 * Time played, split into active and idle, plus a login count.
 *
 * <p>A tick counts as active if the player moved, animated, or was interacting with something.
 * Standing in a bank doing nothing is idle; standing still while chopping a tree is not, since
 * the woodcutting animation is playing.
 */
public class SessionTracker implements Tracker
{
	private final Client client;
	private final TrackerContext ctx;

	private WorldPoint lastLocation;
	private GameState lastState;

	/**
	 * A login is detected before the character is known, since the local player is not populated
	 * the instant the game state flips. The count is held here and banked on the first tick that
	 * has an account to attribute it to.
	 */
	private boolean pendingLogin;

	@Inject
	public SessionTracker(Client client, TrackerContext ctx)
	{
		this.client = client;
		this.ctx = ctx;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		GameState previous = lastState;
		lastState = state;

		if (state != GameState.LOGGED_IN)
		{
			return;
		}

		// LOGGED_IN also fires on every loading screen, so only a transition from the login
		// screen or a hop is a login worth counting.
		if (previous == GameState.LOGGING_IN || previous == GameState.HOPPING)
		{
			pendingLogin = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!ctx.enabled(StatCategory.SESSION) || !ctx.hasActiveAccount())
		{
			return;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}

		if (pendingLogin)
		{
			pendingLogin = false;
			ctx.add(Stats.LOGINS, 1);
		}

		ctx.add(Stats.PLAYTIME, 1);

		WorldPoint location = player.getWorldLocation();
		boolean moved = lastLocation != null && location != null && !lastLocation.equals(location);
		lastLocation = location;

		boolean active = moved || player.getAnimation() != -1 || player.getInteracting() != null;
		ctx.add(active ? Stats.ACTIVE_TIME : Stats.IDLE_TIME, 1);
	}

	@Override
	public void reset()
	{
		lastLocation = null;
		lastState = null;
		pendingLogin = false;
	}
}

package com.woodycode23.lifetracker.trackers;

/**
 * One family of stats.
 *
 * <p>Implementations subscribe to whichever client events they need and call
 * {@link TrackerContext#add} when something happens. They hold only the small amount of
 * per-tick state needed to turn events into deltas, and that state is thrown away by
 * {@link #reset()} whenever continuity is broken (logout, world hop, plugin restart).
 */
public interface Tracker
{
	/**
	 * Drops carry-over state. Called on logout and on shutdown so that, for example, the last
	 * known position from before a world hop cannot be diffed against the first position after
	 * it and be read as a giant walk.
	 */
	void reset();
}

package com.woodycode23.lifetracker.trackers;

import java.time.LocalDate;
import com.woodycode23.lifetracker.LifeTrackerConfig;
import com.woodycode23.lifetracker.stats.StatCatalog;
import com.woodycode23.lifetracker.stats.StatCategory;
import com.woodycode23.lifetracker.stats.StatStore;

/**
 * The only thing a tracker is allowed to touch.
 *
 * <p>Trackers record observations and nothing else. Which account is active, what today's date
 * is, whether a category is switched off, and how any of it is stored all resolve here, so a
 * tracker never has to think about persistence or bucketing.
 */
public class TrackerContext
{
	private final StatStore store;
	private final StatCatalog catalog;
	private final LifeTrackerConfig config;

	public TrackerContext(StatStore store, StatCatalog catalog, LifeTrackerConfig config)
	{
		this.store = store;
		this.catalog = catalog;
		this.config = config;
	}

	public void add(String statId, long amount)
	{
		store.add(statId, amount, LocalDate.now());
	}

	public StatCatalog catalog()
	{
		return catalog;
	}

	public boolean enabled(StatCategory category)
	{
		switch (category)
		{
			case MOVEMENT:
				return config.trackMovement();
			case CONSUMABLES:
				return config.trackConsumables();
			case PRAYER:
				return config.trackPrayer();
			case SESSION:
				return config.trackSession();
			case COMBAT:
				return config.trackCombat();
			default:
				return false;
		}
	}

	/** Calories credited per hitpoint a food restores. */
	public int kcalPerHitpoint()
	{
		return config.kcalPerHitpoint();
	}

	/** Calories credited per potion dose, which mostly restore no hitpoints. */
	public int kcalPerPotionDose()
	{
		return config.kcalPerPotionDose();
	}

	/** False before login, when there is no account to attribute observations to. */
	public boolean hasActiveAccount()
	{
		return store.active() != null;
	}
}

package com.woodycode23.lifetracker.ui;

import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.RenderingHints;
import javax.swing.BorderFactory;
import javax.swing.JPanel;

/**
 * A rounded surface raised off the panel background.
 *
 * <p>Swing has no border radius, so the shape is painted rather than styled: the component is
 * transparent and fills its own rounded rectangle, which lets the background show through at the
 * corners.
 */
public class Card extends JPanel
{
	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBackground(Palette.CARD);
		setBorder(BorderFactory.createEmptyBorder(
			Palette.CARD_PADDING, Palette.CARD_PADDING, Palette.CARD_PADDING, Palette.CARD_PADDING));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(getBackground());
			g.fillRoundRect(0, 0, getWidth(), getHeight(), Palette.CARD_RADIUS, Palette.CARD_RADIUS);
		}
		finally
		{
			g.dispose();
		}
		super.paintComponent(graphics);
	}
}

package com.woodycode23.lifetracker.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import lombok.Getter;
import com.woodycode23.lifetracker.stats.StatCategory;
import com.woodycode23.lifetracker.stats.StatDef;

/**
 * One category, presented the way a Health app card is: a coloured header, a single hero figure
 * with its chart, then the supporting numbers underneath.
 *
 * <p>Only the hero gets a chart. Giving every row its own would triple the panel's height and turn
 * a summary into a wall, which is exactly what the card format is there to avoid.
 */
public class CategoryCard extends Card
{
	@Getter
	private final StatCategory category;

	@Getter
	private final StatDef hero;

	private final Color accent;

	private final JLabel heroValue = new JLabel();
	private final JLabel heroCaption = new JLabel();
	private final MetricChart chart = new MetricChart();
	private final Map<String, ValueRow> rows = new LinkedHashMap<>();

	public CategoryCard(StatCategory category, StatDef hero, List<StatDef> supporting, Runnable onReset)
	{
		super(new BorderLayout());

		this.category = category;
		this.hero = hero;
		this.accent = Palette.accent(category);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setOpaque(false);

		content.add(buildHeader(onReset));
		content.add(Box.createVerticalStrut(6));
		content.add(buildHero());

		chart.setAccent(accent);
		chart.setAlignmentX(LEFT_ALIGNMENT);
		content.add(Box.createVerticalStrut(6));
		content.add(chart);

		if (!supporting.isEmpty())
		{
			content.add(Box.createVerticalStrut(8));
			content.add(new Divider());
			content.add(Box.createVerticalStrut(4));

			for (StatDef def : supporting)
			{
				ValueRow row = new ValueRow(def.getDisplayName());
				rows.put(def.getId(), row);
				content.add(row);
			}
		}

		add(content, BorderLayout.CENTER);
	}

	private JPanel buildHeader(Runnable onReset)
	{
		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		header.setAlignmentX(LEFT_ALIGNMENT);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));

		JLabel title = new JLabel(category.getDisplayName());
		title.setFont(Palette.labelBold());
		title.setForeground(accent);
		title.setIcon(new DotIcon(accent));
		title.setIconTextGap(6);

		ResetButton reset = new ResetButton(accent, "Reset " + category.getDisplayName().toLowerCase(), onReset);

		header.add(title, BorderLayout.CENTER);
		header.add(reset, BorderLayout.EAST);
		return header;
	}

	private JPanel buildHero()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		panel.setAlignmentX(LEFT_ALIGNMENT);

		heroValue.setFont(Palette.METRIC);
		heroValue.setForeground(Palette.TEXT_PRIMARY);
		heroValue.setAlignmentX(LEFT_ALIGNMENT);

		heroCaption.setFont(Palette.label());
		heroCaption.setForeground(Palette.TEXT_SECONDARY);
		heroCaption.setAlignmentX(LEFT_ALIGNMENT);
		heroCaption.setText(hero.getDisplayName());

		panel.add(heroValue);
		panel.add(heroCaption);
		return panel;
	}

	public void updateHero(long value, long[] series, String tooltip)
	{
		heroValue.setText(hero.format(value));
		chart.setSeries(series);
		setToolTipText(tooltip);
	}

	/** Takes an already formatted value, so durations stay durations rather than tick counts. */
	public void updateRow(String statId, String formattedValue, String tooltip)
	{
		ValueRow row = rows.get(statId);
		if (row != null)
		{
			row.setValue(formattedValue, tooltip);
		}
	}

	public boolean hasRow(String statId)
	{
		return rows.containsKey(statId);
	}

	/** Name on the left, number on the right, one line. */
	private static final class ValueRow extends JPanel
	{
		private final JLabel value = new JLabel();

		ValueRow(String name)
		{
			super(new BorderLayout(4, 0));
			setOpaque(false);
			setAlignmentX(LEFT_ALIGNMENT);
			setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));

			JLabel label = new JLabel(name);
			label.setFont(Palette.label());
			label.setForeground(Palette.TEXT_SECONDARY);

			value.setFont(Palette.ROW_VALUE);
			value.setForeground(Palette.TEXT_PRIMARY);
			value.setHorizontalAlignment(JLabel.RIGHT);

			add(label, BorderLayout.CENTER);
			add(value, BorderLayout.EAST);
		}

		void setValue(String formatted, String tooltip)
		{
			value.setText(formatted);
			setToolTipText(tooltip);
		}
	}

	/** Hairline between the hero and the supporting numbers. */
	private static final class Divider extends JComponent
	{
		Divider()
		{
			setPreferredSize(new Dimension(0, 1));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
			setAlignmentX(LEFT_ALIGNMENT);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			g.setColor(Palette.DIVIDER);
			g.fillRect(0, 0, getWidth(), 1);
		}
	}

	/** The category's colour, as a small filled circle beside its name. */
	private static final class DotIcon implements javax.swing.Icon
	{
		private static final int SIZE = 8;
		private final Color color;

		DotIcon(Color color)
		{
			this.color = color;
		}

		@Override
		public void paintIcon(java.awt.Component c, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g.setColor(color);
				g.fillOval(x, y, SIZE, SIZE);
			}
			finally
			{
				g.dispose();
			}
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return SIZE;
		}
	}
}

package com.woodycode23.lifetracker.ui;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.datatransfer.StringSelection;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import com.woodycode23.lifetracker.Comparisons;
import com.woodycode23.lifetracker.LifeTrackerConfig;
import com.woodycode23.lifetracker.stats.AccountStats;
import com.woodycode23.lifetracker.stats.Period;
import com.woodycode23.lifetracker.stats.StatCatalog;
import com.woodycode23.lifetracker.stats.StatCategory;
import com.woodycode23.lifetracker.stats.StatDef;
import com.woodycode23.lifetracker.stats.StatSelection;
import com.woodycode23.lifetracker.stats.StatStore;
import net.runelite.client.ui.PluginPanel;

/**
 * Two pages: the summary, and the picker that decides what the summary contains.
 *
 * <p>Layout and value updates stay separate. {@link #rebuild()} is the expensive path and runs only
 * when the shape of the data changes: a different account or period, a changed selection, or a stat
 * recorded for the first time. {@link #refresh()} runs several times a second while you play and
 * only writes text into labels that already exist.
 */
public class LifeTrackerPanel extends PluginPanel
{
	private enum Page
	{
		SUMMARY("Summary"),
		TRACKING("Tracking");

		private final String label;

		Page(String label)
		{
			this.label = label;
		}
	}

	private static final String ALL_ACCOUNTS = "All accounts";
	private static final DateTimeFormatter RECORD_DATE = DateTimeFormatter.ofPattern("d MMM yyyy");

	private final StatStore store;
	private final StatCatalog catalog;
	private final StatSelection selection;
	private final LifeTrackerConfig config;
	private final Runnable onReset;

	private final JComboBox<String> accountSelector = new JComboBox<>();
	private final PillSelector<Period> periodControl;
	private final PillSelector<Page> pageControl;

	private final JPanel body = new JPanel();
	private final JPanel summaryPage = new JPanel();
	private final TrackingPage trackingPage;

	private final StreakRing streakRing = new StreakRing();
	private final JLabel streakCaption = new JLabel();
	private final JLabel streakDetail = new JLabel();

	private final Map<StatCategory, CategoryCard> cards = new LinkedHashMap<>();

	private Page page = Page.SUMMARY;
	private Period period;
	private String selectedAccountKey;
	private Set<String> laidOutStatIds = new LinkedHashSet<>();
	private boolean updatingSelector;

	public LifeTrackerPanel(StatStore store, StatCatalog catalog, StatSelection selection,
		LifeTrackerConfig config, Runnable onReset)
	{
		this.store = store;
		this.catalog = catalog;
		this.selection = selection;
		this.config = config;
		this.onReset = onReset;
		this.period = config.defaultPeriod();

		this.periodControl = new PillSelector<>(Period.values(), Period::getDisplayName, period, selected -> {
			period = selected;
			rebuild();
		});
		this.pageControl = new PillSelector<>(Page.values(), p -> p.label, page, selected -> {
			page = selected;
			rebuild();
		});
		this.trackingPage = new TrackingPage(catalog, store, selection, this::rebuild);

		setBackground(Palette.BACKGROUND);
		setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));

		add(buildHeader());

		body.setLayout(new BorderLayout());
		body.setOpaque(false);
		add(body);

		summaryPage.setLayout(new BoxLayout(summaryPage, BoxLayout.Y_AXIS));
		summaryPage.setOpaque(false);

		rebuild();
	}

	// -- construction -----------------------------------------------------

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setOpaque(false);

		JLabel title = new JLabel("Life Tracker");
		title.setFont(Palette.METRIC_SMALL);
		title.setForeground(Palette.TEXT_PRIMARY);
		title.setAlignmentX(LEFT_ALIGNMENT);

		pageControl.setAlignmentX(LEFT_ALIGNMENT);

		header.add(title);
		header.add(Box.createVerticalStrut(6));
		header.add(pageControl);
		header.add(Box.createVerticalStrut(Palette.CARD_GAP));
		return header;
	}

	private JPanel buildSummaryControls()
	{
		JPanel controls = new JPanel();
		controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
		controls.setOpaque(false);
		controls.setAlignmentX(LEFT_ALIGNMENT);

		accountSelector.setFocusable(false);
		accountSelector.setFont(Palette.label());
		accountSelector.setBackground(Palette.CARD);
		accountSelector.setForeground(Palette.TEXT_PRIMARY);
		accountSelector.setAlignmentX(LEFT_ALIGNMENT);
		accountSelector.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

		for (java.awt.event.ActionListener listener : accountSelector.getActionListeners())
		{
			accountSelector.removeActionListener(listener);
		}
		accountSelector.addActionListener(e -> {
			if (updatingSelector)
			{
				return;
			}

			int index = accountSelector.getSelectedIndex();
			selectedAccountKey = index <= 0 ? null : StatStore.keyFor((String) accountSelector.getItemAt(index));
			rebuild();
		});

		periodControl.setAlignmentX(LEFT_ALIGNMENT);

		controls.add(accountSelector);
		controls.add(Box.createVerticalStrut(6));
		controls.add(periodControl);
		controls.add(Box.createVerticalStrut(Palette.CARD_GAP));
		return controls;
	}

	/** The signature: streak ring on the left, its supporting text on the right. */
	private JPanel buildSummaryCard()
	{
		Card card = new Card(new BorderLayout(10, 0));

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setOpaque(false);

		streakCaption.setFont(Palette.labelBold());
		streakCaption.setForeground(Palette.TEXT_PRIMARY);
		streakCaption.setAlignmentX(LEFT_ALIGNMENT);

		streakDetail.setFont(Palette.label());
		streakDetail.setForeground(Palette.TEXT_SECONDARY);
		streakDetail.setAlignmentX(LEFT_ALIGNMENT);

		text.add(Box.createVerticalGlue());
		text.add(streakCaption);
		text.add(Box.createVerticalStrut(2));
		text.add(streakDetail);
		text.add(Box.createVerticalGlue());

		card.add(streakRing, BorderLayout.WEST);
		card.add(text, BorderLayout.CENTER);
		card.setAlignmentX(LEFT_ALIGNMENT);
		return card;
	}

	private JPanel buildFooter()
	{
		JPanel footer = new JPanel(new GridLayout(1, 2, 6, 0));
		footer.setOpaque(false);
		footer.setAlignmentX(LEFT_ALIGNMENT);
		footer.setBorder(BorderFactory.createEmptyBorder(Palette.CARD_GAP, 0, 0, 0));
		footer.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

		JButton export = new JButton("Copy JSON");
		export.setFont(Palette.label());
		export.setFocusable(false);
		export.setToolTipText("Copy the full history for the current selection to the clipboard");
		export.addActionListener(e -> copyExport());

		JButton reset = new JButton("Reset all");
		reset.setFont(Palette.label());
		reset.setFocusable(false);
		reset.setToolTipText("Permanently delete every tracked stat for the current selection");
		reset.addActionListener(e -> confirmResetAll());

		footer.add(export);
		footer.add(reset);
		return footer;
	}

	// -- layout -----------------------------------------------------------

	public void rebuild()
	{
		SwingUtilities.invokeLater(() -> {
			pageControl.setSelected(page);
			body.removeAll();

			if (page == Page.TRACKING)
			{
				trackingPage.rebuild();
				body.add(trackingPage, BorderLayout.CENTER);
			}
			else
			{
				buildSummary();
				body.add(summaryPage, BorderLayout.CENTER);
			}

			body.revalidate();
			body.repaint();
		});
	}

	private void buildSummary()
	{
		syncAccountSelector();
		periodControl.setSelected(period);

		summaryPage.removeAll();
		cards.clear();

		summaryPage.add(buildSummaryControls());
		summaryPage.add(buildSummaryCard());
		summaryPage.add(Box.createVerticalStrut(Palette.CARD_GAP));

		Set<String> visible = visibleStatIds();
		laidOutStatIds = visible;

		for (StatCategory category : StatCategory.values())
		{
			List<StatDef> defs = new ArrayList<>();
			for (StatDef def : orderedStats(category))
			{
				if (visible.contains(def.getId()))
				{
					defs.add(def);
				}
			}

			if (defs.isEmpty())
			{
				continue;
			}

			// The first stat by sort order is the category's headline figure by design.
			StatDef hero = defs.get(0);
			List<StatDef> supporting = defs.subList(1, defs.size());

			CategoryCard card = new CategoryCard(category, hero, supporting, () -> confirmResetCategory(category));
			card.setAlignmentX(LEFT_ALIGNMENT);
			cards.put(category, card);

			summaryPage.add(card);
			summaryPage.add(Box.createVerticalStrut(Palette.CARD_GAP));
		}

		if (cards.isEmpty())
		{
			summaryPage.add(emptyState());
		}

		summaryPage.add(buildFooter());
		refreshValues();
	}

	/** Catalog order, plus anything discovered that the catalog learned about after startup. */
	private List<StatDef> orderedStats(StatCategory category)
	{
		Set<String> ids = new LinkedHashSet<>();
		for (StatDef def : catalog.byCategory(category))
		{
			ids.add(def.getId());
		}
		for (String id : store.trackedStatIds(selectedAccountKey))
		{
			if (catalog.get(id).getCategory() == category)
			{
				ids.add(id);
			}
		}

		List<StatDef> defs = new ArrayList<>();
		for (String id : ids)
		{
			defs.add(catalog.get(id));
		}
		defs.sort((a, b) -> {
			int order = Integer.compare(a.getSortOrder(), b.getSortOrder());
			return order != 0 ? order : a.getDisplayName().compareToIgnoreCase(b.getDisplayName());
		});
		return defs;
	}

	/**
	 * Stats with no history stay hidden by default, so a fresh account is a short panel that grows
	 * as you play. On top of that, anything switched off on the tracking page is excluded.
	 */
	private Set<String> visibleStatIds()
	{
		Set<String> candidates = new LinkedHashSet<>();

		if (config.showZeroStats())
		{
			for (StatCategory category : StatCategory.values())
			{
				for (StatDef def : catalog.byCategory(category))
				{
					candidates.add(def.getId());
				}
			}
		}

		candidates.addAll(store.trackedStatIds(selectedAccountKey));

		Set<String> visible = new LinkedHashSet<>();
		for (String id : candidates)
		{
			if (selection.isVisible(id))
			{
				visible.add(id);
			}
		}
		return visible;
	}

	private JLabel emptyState()
	{
		JLabel label = new JLabel("<html>Nothing tracked yet.<br>Log in and start playing.</html>");
		label.setFont(Palette.label());
		label.setForeground(Palette.TEXT_SECONDARY);
		label.setAlignmentX(LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(8, 2, 8, 2));
		return label;
	}

	private void syncAccountSelector()
	{
		List<String> names = store.accountNames();

		updatingSelector = true;
		try
		{
			accountSelector.removeAllItems();
			accountSelector.addItem(ALL_ACCOUNTS);
			for (String name : names)
			{
				accountSelector.addItem(name);
			}

			accountSelector.setSelectedIndex(0);
			if (selectedAccountKey != null)
			{
				for (int i = 0; i < names.size(); i++)
				{
					if (StatStore.keyFor(names.get(i)).equals(selectedAccountKey))
					{
						accountSelector.setSelectedIndex(i + 1);
						break;
					}
				}
			}
		}
		finally
		{
			updatingSelector = false;
		}
	}

	// -- live updates -----------------------------------------------------

	public void refresh()
	{
		SwingUtilities.invokeLater(() -> {
			if (page != Page.SUMMARY)
			{
				return;
			}

			// A stat seen for the first time needs a row building, which refresh cannot do.
			for (String id : store.trackedStatIds(selectedAccountKey))
			{
				if (!laidOutStatIds.contains(id) && selection.isVisible(id))
				{
					rebuild();
					return;
				}
			}
			refreshValues();
		});
	}

	private void refreshValues()
	{
		LocalDate today = LocalDate.now();

		int streak = store.currentStreak(selectedAccountKey, today);
		int best = store.bestStreak(selectedAccountKey);
		streakRing.setStreak(streak);
		streakCaption.setText(streak == 1 ? "1 day streak" : streak + " day streak");
		streakDetail.setText(best > 0 ? "Best " + best : "Play daily to start one");

		for (CategoryCard card : cards.values())
		{
			StatDef hero = card.getHero();
			card.updateHero(
				store.value(selectedAccountKey, hero.getId(), period, today),
				store.series(selectedAccountKey, hero.getId(), period.chartPeriod(), today),
				tooltipFor(hero, today));

			for (StatDef def : orderedStats(card.getCategory()))
			{
				if (card.hasRow(def.getId()))
				{
					long value = store.value(selectedAccountKey, def.getId(), period, today);
					card.updateRow(def.getId(), def.format(value), tooltipFor(def, today));
				}
			}
		}
	}

	private String tooltipFor(StatDef def, LocalDate today)
	{
		StringBuilder tooltip = new StringBuilder("<html>");
		tooltip.append("<b>").append(def.getDisplayName()).append("</b>");
		tooltip.append("<br>All time: ").append(def.format(store.value(selectedAccountKey, def.getId(), Period.ALL, today)));

		AccountStats.DayRecord record = store.record(selectedAccountKey, def.getId());
		if (record != null && record.value > 0)
		{
			tooltip.append("<br>Best day: ").append(def.format(record.value));
			if (record.day != null)
			{
				tooltip.append(" on ").append(RECORD_DATE.format(LocalDate.parse(record.day)));
			}
		}

		if (config.showComparisons())
		{
			long value = store.value(selectedAccountKey, def.getId(), period, today);
			for (String line : Comparisons.forStat(def, value, config.centimetresPerTile()))
			{
				tooltip.append("<br>").append(line);
			}
		}

		return tooltip.append("</html>").toString();
	}

	// -- actions ----------------------------------------------------------

	private void copyExport()
	{
		String json = store.exportJson(selectedAccountKey);
		java.awt.Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(json), null);
		JOptionPane.showMessageDialog(this, "History copied to the clipboard.", "Life Tracker", JOptionPane.INFORMATION_MESSAGE);
	}

	private void confirmResetCategory(StatCategory category)
	{
		List<String> ids = new ArrayList<>();
		for (StatDef def : orderedStats(category))
		{
			ids.add(def.getId());
		}

		if (!confirm("Reset " + category.getDisplayName().toLowerCase() + " stats for " + targetName() + "?"))
		{
			return;
		}

		store.resetStats(selectedAccountKey, ids, LocalDate.now());
		rebuild();
	}

	private void confirmResetAll()
	{
		if (!confirm("Delete every tracked stat for " + targetName() + "?"))
		{
			return;
		}

		store.reset(selectedAccountKey);
		selectedAccountKey = null;
		onReset.run();
		rebuild();
	}

	private boolean confirm(String message)
	{
		return JOptionPane.showConfirmDialog(this, message, "Life Tracker",
			JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION;
	}

	private String targetName()
	{
		Object selected = accountSelector.getSelectedItem();
		return selectedAccountKey == null || selected == null ? "every account" : selected.toString();
	}
}

package com.woodycode23.lifetracker.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/**
 * Rounded bars, one per day or month of the selected period, in the category's accent colour.
 *
 * <p>Bars scale to the largest value in the series rather than to a fixed ceiling, so a quiet week
 * is as legible as a busy one. Empty periods still draw a faint track, which keeps the chart the
 * same visual weight whether or not there is data and stops cards from jumping around as numbers
 * arrive.
 */
public class MetricChart extends JComponent
{
	private static final int HEIGHT = 34;
	private static final int GAP = 2;
	private static final int MIN_BAR = 2;

	private long[] series = new long[0];
	private Color accent = Palette.TEXT_SECONDARY;

	public MetricChart()
	{
		setPreferredSize(new Dimension(0, HEIGHT));
		setMinimumSize(new Dimension(0, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
	}

	public void setAccent(Color accent)
	{
		this.accent = accent;
	}

	public void setSeries(long[] series)
	{
		this.series = series == null ? new long[0] : series;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		if (series.length == 0)
		{
			return;
		}

		int width = getWidth();
		int height = getHeight();
		if (width <= 0)
		{
			return;
		}

		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			long max = 0;
			for (long value : series)
			{
				max = Math.max(max, value);
			}

			int barWidth = Math.max(2, (width - (series.length - 1) * GAP) / series.length);
			int radius = Math.min(barWidth, 6);

			for (int i = 0; i < series.length; i++)
			{
				int x = i * (barWidth + GAP);

				// Faint full-height track, so the chart keeps its shape on empty days.
				g.setColor(Palette.fade(Palette.TEXT_TERTIARY, 40));
				g.fillRoundRect(x, 0, barWidth, height, radius, radius);

				if (max <= 0 || series[i] <= 0)
				{
					continue;
				}

				int barHeight = Math.max(MIN_BAR, (int) Math.round((series[i] / (double) max) * height));
				boolean latest = i == series.length - 1;

				g.setColor(latest ? accent : Palette.fade(accent, 150));
				g.fillRoundRect(x, height - barHeight, barWidth, barHeight, radius, radius);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.woodycode23.lifetracker.ui;

import java.awt.Color;
import java.awt.Font;
import com.woodycode23.lifetracker.stats.StatCategory;
import net.runelite.client.ui.FontManager;

/**
 * The panel's design tokens in one place.
 *
 * <p>Accents are the Apple dark mode system colours, one hue per category, which is the device
 * that makes a stack of cards read as a Health summary rather than a table with colour on it.
 *
 * <p>Type is a deliberate pairing rather than one family throughout: metric values are set in a
 * clean sans because that is what gives the numbers their weight, while labels and captions keep
 * RuneLite's pixel font. Scaling the pixel font up to headline size only makes it look broken, so
 * it stays in the utility role where it reads well and keeps the panel unmistakably OSRS.
 */
public final class Palette
{
	public static final Color BACKGROUND = new Color(0x1E1E1E);
	public static final Color CARD = new Color(0x2A2A2A);
	public static final Color CARD_HOVER = new Color(0x323232);
	public static final Color DIVIDER = new Color(0x3A3A3A);

	public static final Color TEXT_PRIMARY = new Color(0xFFFFFF);
	public static final Color TEXT_SECONDARY = new Color(0x9A9A9A);
	public static final Color TEXT_TERTIARY = new Color(0x6E6E6E);

	public static final Color MOVEMENT = new Color(0xFF9F0A);
	public static final Color CONSUMABLES = new Color(0x32D74B);
	public static final Color PRAYER = new Color(0x64D2FF);
	public static final Color SESSION = new Color(0xBF5AF2);
	public static final Color COMBAT = new Color(0xFF453A);

	public static final int CARD_RADIUS = 12;
	public static final int CARD_PADDING = 10;
	public static final int CARD_GAP = 8;

	/** Metric values. A sans face at size is what carries the Health app's numeric weight. */
	public static final Font METRIC = new Font(Font.SANS_SERIF, Font.BOLD, 22);
	public static final Font METRIC_SMALL = new Font(Font.SANS_SERIF, Font.BOLD, 13);
	public static final Font UNIT = new Font(Font.SANS_SERIF, Font.PLAIN, 11);
	public static final Font ROW_VALUE = new Font(Font.SANS_SERIF, Font.PLAIN, 12);

	/** Footnote scale, for things that must be present without being noticed. */
	public static final Font MICRO = new Font(Font.SANS_SERIF, Font.PLAIN, 9);

	/** Dimmer than tertiary. Legible on inspection, invisible at a glance. */
	public static final Color TEXT_FAINT = new Color(0x555555);

	public static Font label()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Font labelBold()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Color accent(StatCategory category)
	{
		switch (category)
		{
			case MOVEMENT:
				return MOVEMENT;
			case CONSUMABLES:
				return CONSUMABLES;
			case PRAYER:
				return PRAYER;
			case SESSION:
				return SESSION;
			case COMBAT:
				return COMBAT;
			default:
				return TEXT_SECONDARY;
		}
	}

	public static Color fade(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}

	private Palette()
	{
	}
}

package com.woodycode23.lifetracker.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.JComponent;

/**
 * A row of choices drawn as one pill with the selection highlighted.
 *
 * <p>Used for both the period picker and the page switcher. Separate Swing buttons at 225px wrap
 * and each carry their own chrome; one painted control keeps the row to a single line and reads as
 * the segmented control it is imitating.
 */
public class PillSelector<T> extends JComponent
{
	private static final int HEIGHT = 24;
	private static final int RADIUS = 12;
	private static final int INSET = 2;

	private final T[] options;
	private final Function<T, String> labeller;
	private final Consumer<T> onSelect;

	private T selected;
	private int hovered = -1;

	public PillSelector(T[] options, Function<T, String> labeller, T initial, Consumer<T> onSelect)
	{
		this.options = options;
		this.labeller = labeller;
		this.selected = initial;
		this.onSelect = onSelect;

		setPreferredSize(new Dimension(0, HEIGHT));
		setMinimumSize(new Dimension(0, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setCursor(new Cursor(Cursor.HAND_CURSOR));
		setFont(Palette.label());

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index >= 0)
				{
					setSelected(PillSelector.this.options[index]);
					PillSelector.this.onSelect.accept(PillSelector.this.options[index]);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hovered = -1;
				repaint();
			}
		});

		addMouseMotionListener(new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hovered)
				{
					hovered = index;
					repaint();
				}
			}
		});
	}

	public void setSelected(T option)
	{
		this.selected = option;
		repaint();
	}

	private int indexAt(int x)
	{
		if (getWidth() <= 0)
		{
			return -1;
		}
		int index = x * options.length / getWidth();
		return index < 0 || index >= options.length ? -1 : index;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			int width = getWidth();
			int height = getHeight();

			g.setColor(Palette.CARD);
			g.fillRoundRect(0, 0, width, height, RADIUS, RADIUS);

			int segmentWidth = width / options.length;
			g.setFont(getFont());
			FontMetrics metrics = g.getFontMetrics();

			for (int i = 0; i < options.length; i++)
			{
				int x = i * segmentWidth;
				boolean isSelected = options[i].equals(selected);

				if (isSelected || i == hovered)
				{
					g.setColor(Palette.fade(Palette.TEXT_PRIMARY, isSelected ? 28 : 12));
					g.fillRoundRect(x + INSET, INSET, segmentWidth - INSET * 2, height - INSET * 2, RADIUS, RADIUS);
				}

				String text = labeller.apply(options[i]);
				g.setColor(isSelected ? Palette.TEXT_PRIMARY : Palette.TEXT_SECONDARY);
				g.drawString(text,
					x + (segmentWidth - metrics.stringWidth(text)) / 2,
					height / 2 + metrics.getAscent() / 2 - 1);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.woodycode23.lifetracker.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;

/**
 * The circular reset control that sits in each card header.
 *
 * <p>Drawn rather than typed: the obvious glyph for this is U+21BA, and font coverage for it is
 * not dependable across platforms, so a missing glyph would render as a box. An arc with an
 * arrowhead always looks the same everywhere.
 *
 * <p>It sits at low opacity until hovered, so five of them down the panel stay quiet.
 */
public class ResetButton extends JComponent
{
	private static final int SIZE = 16;

	private final Runnable onClick;
	private Color accent;
	private boolean hovered;

	public ResetButton(Color accent, String tooltip, Runnable onClick)
	{
		this.accent = accent;
		this.onClick = onClick;

		Dimension size = new Dimension(SIZE, SIZE);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		setCursor(new Cursor(Cursor.HAND_CURSOR));
		setToolTipText(tooltip);

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				ResetButton.this.onClick.run();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				hovered = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hovered = false;
				repaint();
			}
		});
	}

	public void setAccent(Color accent)
	{
		this.accent = accent;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(hovered ? accent : Palette.fade(accent, 110));
			g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

			int inset = 3;
			int diameter = SIZE - inset * 2;

			// Open arc, with the gap at the top right where the arrowhead goes.
			g.drawArc(inset, inset, diameter, diameter, 60, 290);

			int tipX = inset + diameter;
			int tipY = inset + diameter / 2;
			Polygon head = new Polygon();
			head.addPoint(tipX, tipY - 4);
			head.addPoint(tipX - 3, tipY + 1);
			head.addPoint(tipX + 3, tipY + 1);
			g.fillPolygon(head);
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.woodycode23.lifetracker.ui;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/**
 * The login streak as a closing ring.
 *
 * <p>This is the panel's signature: the one Health app idea that translates honestly to an OSRS
 * character. The ring fills against a seven day week, so a full circle means you have played every
 * day this week, and the number in the middle is the streak itself. Past seven days the ring stays
 * closed and the number keeps climbing, which is the point.
 */
public class StreakRing extends JComponent
{
	private static final int SIZE = 64;
	private static final int THICKNESS = 7;
	private static final int TARGET_DAYS = 7;

	private int streak;

	public StreakRing()
	{
		Dimension size = new Dimension(SIZE, SIZE);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
	}

	public void setStreak(int streak)
	{
		this.streak = streak;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			int inset = THICKNESS / 2 + 1;
			int diameter = SIZE - inset * 2;

			g.setStroke(new BasicStroke(THICKNESS, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

			g.setColor(Palette.fade(Palette.MOVEMENT, 45));
			g.drawArc(inset, inset, diameter, diameter, 0, 360);

			if (streak > 0)
			{
				double progress = Math.min(1d, streak / (double) TARGET_DAYS);
				// Start at twelve o'clock and close clockwise.
				g.setColor(Palette.MOVEMENT);
				g.drawArc(inset, inset, diameter, diameter, 90, -(int) Math.round(progress * 360));
			}

			g.setFont(Palette.METRIC_SMALL);
			g.setColor(Palette.TEXT_PRIMARY);

			String text = String.valueOf(streak);
			FontMetrics metrics = g.getFontMetrics();
			int textX = (SIZE - metrics.stringWidth(text)) / 2;
			int textY = SIZE / 2 + metrics.getAscent() / 2 - 2;
			g.drawString(text, textX, textY);
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.woodycode23.lifetracker.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import com.woodycode23.lifetracker.stats.StatCatalog;
import com.woodycode23.lifetracker.stats.StatCategory;
import com.woodycode23.lifetracker.stats.StatDef;
import com.woodycode23.lifetracker.stats.StatSelection;
import com.woodycode23.lifetracker.stats.StatStore;

/**
 * The second page: what the summary shows.
 *
 * <p>One card per category, matching the summary's colour coding, holding a checkbox per stat.
 * Individual potions, foods and prayers appear here as soon as they have been seen once, so the
 * list grows to match how you actually play rather than listing every consumable in the game.
 *
 * <p>Toggling is display only. The category switches in the plugin's RuneLite settings control
 * whether something is recorded at all, so nothing here can lose history.
 */
public class TrackingPage extends JPanel
{
	private final StatCatalog catalog;
	private final StatStore store;
	private final StatSelection selection;
	private final Runnable onChanged;

	public TrackingPage(StatCatalog catalog, StatStore store, StatSelection selection, Runnable onChanged)
	{
		this.catalog = catalog;
		this.store = store;
		this.selection = selection;
		this.onChanged = onChanged;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);

		rebuild();
	}

	public void rebuild()
	{
		removeAll();

		// Two plain labels rather than one wrapping HTML label. An HTML label inside a BoxLayout
		// computes its height from a width it does not know yet, so it clips; pinning a size
		// instead makes it wrap and centre. Plain labels just size correctly.
		add(introLine("What the summary shows."));
		add(introLine("Hidden stats keep counting."));
		add(Box.createVerticalStrut(8));

		for (StatCategory category : StatCategory.values())
		{
			List<StatDef> defs = knownStats(category);
			if (defs.isEmpty())
			{
				continue;
			}

			add(buildCategory(category, defs));
			add(Box.createVerticalStrut(Palette.CARD_GAP));
		}

		revalidate();
		repaint();
	}

	private JLabel introLine(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(Palette.label());
		label.setForeground(Palette.TEXT_SECONDARY);
		label.setAlignmentX(LEFT_ALIGNMENT);
		label.setHorizontalAlignment(JLabel.LEFT);
		label.setBorder(BorderFactory.createEmptyBorder(0, 2, 1, 2));
		// No size constraints: capping the height squeezes the label and Swing responds by
		// truncating the text. Its natural preferred size is already correct.
		return label;
	}

	/** Fixed stats plus anything discovered, so newly eaten foods show up without a restart. */
	private List<StatDef> knownStats(StatCategory category)
	{
		Set<String> ids = new LinkedHashSet<>();
		for (StatDef def : catalog.byCategory(category))
		{
			ids.add(def.getId());
		}
		for (String id : store.trackedStatIds(null))
		{
			if (catalog.get(id).getCategory() == category)
			{
				ids.add(id);
			}
		}

		List<StatDef> defs = new ArrayList<>();
		for (String id : ids)
		{
			defs.add(catalog.get(id));
		}
		defs.sort((a, b) -> {
			int order = Integer.compare(a.getSortOrder(), b.getSortOrder());
			return order != 0 ? order : a.getDisplayName().compareToIgnoreCase(b.getDisplayName());
		});
		return defs;
	}

	private JPanel buildCategory(StatCategory category, List<StatDef> defs)
	{
		Color accent = Palette.accent(category);
		Card card = new Card(new BorderLayout());
		// Every child of this BoxLayout must share an alignment. Mixing CENTER cards with LEFT
		// labels makes BoxLayout align them to a common axis, which shoves the labels rightwards.
		card.setAlignmentX(LEFT_ALIGNMENT);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setOpaque(false);

		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		header.setAlignmentX(LEFT_ALIGNMENT);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));

		JLabel title = new JLabel(category.getDisplayName());
		title.setFont(Palette.labelBold());
		title.setForeground(accent);

		header.add(title, BorderLayout.CENTER);
		header.add(buildBulkToggle(defs, accent), BorderLayout.EAST);

		content.add(header);
		content.add(Box.createVerticalStrut(4));

		for (StatDef def : defs)
		{
			content.add(buildCheckbox(def, accent));
		}

		card.add(content, BorderLayout.CENTER);
		return card;
	}

	/** One click to show or hide a whole category, which matters once you have 30 foods. */
	private JLabel buildBulkToggle(List<StatDef> defs, Color accent)
	{
		boolean anyVisible = defs.stream().anyMatch(def -> selection.isVisible(def.getId()));

		JLabel toggle = new JLabel(anyVisible ? "Hide all" : "Show all");
		toggle.setFont(Palette.label());
		toggle.setForeground(Palette.fade(accent, 170));
		toggle.setCursor(new Cursor(Cursor.HAND_CURSOR));
		toggle.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				List<String> ids = new ArrayList<>();
				for (StatDef def : defs)
				{
					ids.add(def.getId());
				}
				selection.setVisible(ids, !anyVisible);
				rebuild();
				onChanged.run();
			}
		});
		return toggle;
	}

	private JCheckBox buildCheckbox(StatDef def, Color accent)
	{
		JCheckBox box = new JCheckBox(def.getDisplayName(), selection.isVisible(def.getId()));
		box.setFont(Palette.label());
		box.setForeground(selection.isVisible(def.getId()) ? Palette.TEXT_PRIMARY : Palette.TEXT_TERTIARY);
		box.setOpaque(false);
		box.setFocusable(false);
		box.setAlignmentX(LEFT_ALIGNMENT);
		box.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		box.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		box.addActionListener(e -> {
			selection.setVisible(def.getId(), box.isSelected());
			box.setForeground(box.isSelected() ? Palette.TEXT_PRIMARY : Palette.TEXT_TERTIARY);
			onChanged.run();
		});
		return box;
	}
}

package com.woodycode23.lifetracker;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class CaloriesTest
{
	private static final int DEFAULT_PER_HITPOINT = 10;
	private static final int DEFAULT_PER_DOSE = 15;

	/**
	 * The justification for the default factor, pinned so it cannot drift silently. These are the
	 * foods people actually eat, and at 10 per hitpoint each lands within about a tenth of the real
	 * world calorie count for the same fish.
	 */
	@Test
	public void staplesLandNearTheirRealWorldCalorieCounts()
	{
		assertEquals("shark", 200, Calories.fromHealing(20, 1, DEFAULT_PER_HITPOINT));
		assertEquals("manta ray", 220, Calories.fromHealing(22, 1, DEFAULT_PER_HITPOINT));
		assertEquals("karambwan", 180, Calories.fromHealing(18, 1, DEFAULT_PER_HITPOINT));
		assertEquals("lobster", 120, Calories.fromHealing(12, 1, DEFAULT_PER_HITPOINT));
		assertEquals("tuna", 100, Calories.fromHealing(10, 1, DEFAULT_PER_HITPOINT));
	}

	/** The session that prompted the rebalance: five items that used to read as a day's eating. */
	@Test
	public void theFiveItemSessionIsNoLongerAFullDayOfFood()
	{
		long anglerfish = Calories.fromHealing(22, 1, DEFAULT_PER_HITPOINT);
		long mantaRay = Calories.fromHealing(22, 1, DEFAULT_PER_HITPOINT);
		long shark = Calories.fromHealing(20, 1, DEFAULT_PER_HITPOINT);
		long karambwans = Calories.fromHealing(18, 2, DEFAULT_PER_HITPOINT);

		assertEquals(1_000, anglerfish + mantaRay + shark + karambwans);
	}

	@Test
	public void countMultipliesTheItemValue()
	{
		assertEquals(600, Calories.fromHealing(20, 3, DEFAULT_PER_HITPOINT));
	}

	/** Divine potions heal a negative amount; that must not subtract calories. */
	@Test
	public void damagingItemsAreWorthNothingRatherThanNegative()
	{
		assertEquals(0, Calories.fromHealing(-10, 1, DEFAULT_PER_HITPOINT));
	}

	@Test
	public void itemsThatHealNothingAreFree()
	{
		assertEquals(0, Calories.fromHealing(0, 4, DEFAULT_PER_HITPOINT));
	}

	@Test
	public void dosesAreChargedFlat()
	{
		assertEquals(15, Calories.fromDoses(1, DEFAULT_PER_DOSE));
		assertEquals(450, Calories.fromDoses(30, DEFAULT_PER_DOSE));
	}

	/** Setting the dose value to zero must fall back to a pure hitpoints-healed rule. */
	@Test
	public void zeroPerDoseDisablesPotionCalories()
	{
		assertEquals(0, Calories.fromDoses(30, 0));
	}

	@Test
	public void negativeAndZeroCountsContributeNothing()
	{
		assertEquals(0, Calories.fromHealing(20, 0, DEFAULT_PER_HITPOINT));
		assertEquals(0, Calories.fromDoses(0, DEFAULT_PER_DOSE));
	}
}

package com.woodycode23.lifetracker;

import java.util.List;
import com.woodycode23.lifetracker.stats.StatCatalog;
import com.woodycode23.lifetracker.stats.StatDef;
import com.woodycode23.lifetracker.stats.StatUnit;
import com.woodycode23.lifetracker.stats.Stats;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ComparisonsTest
{
	private static final int ONE_METRE_PER_TILE = 100;

	private final StatCatalog catalog = new StatCatalog();

	@Test
	public void zeroProducesNothingToSay()
	{
		StatDef tiles = catalog.get(Stats.TILES_TOTAL);
		assertTrue(Comparisons.forStat(tiles, 0, ONE_METRE_PER_TILE).isEmpty());
	}

	@Test
	public void shortDistancesStayInMetres()
	{
		StatDef tiles = catalog.get(Stats.TILES_TOTAL);
		List<String> lines = Comparisons.forStat(tiles, 250, ONE_METRE_PER_TILE);

		assertEquals(1, lines.size());
		assertTrue(lines.get(0), lines.get(0).contains("250 metres"));
	}

	@Test
	public void longDistancesConvertToKilometresAndAMarathonCount()
	{
		StatDef tiles = catalog.get(Stats.TILES_TOTAL);
		List<String> lines = Comparisons.forStat(tiles, 100_000, ONE_METRE_PER_TILE);

		assertEquals(2, lines.size());
		assertTrue(lines.get(0), lines.get(0).contains("100.00 km"));
		assertTrue(lines.get(1), lines.get(1).contains("marathons"));
	}

	@Test
	public void tileSizeSettingScalesTheDistance()
	{
		StatDef tiles = catalog.get(Stats.TILES_TOTAL);

		List<String> oneMetre = Comparisons.forStat(tiles, 1_000, 100);
		List<String> twoMetres = Comparisons.forStat(tiles, 1_000, 200);

		assertTrue(oneMetre.get(0), oneMetre.get(0).contains("1.00 km"));
		assertTrue(twoMetres.get(0), twoMetres.get(0).contains("2.00 km"));
	}

	@Test
	public void dosesBecomeFullPotions()
	{
		StatDef doses = catalog.get(Stats.POTION_DOSES);
		List<String> lines = Comparisons.forStat(doses, 10, ONE_METRE_PER_TILE);

		assertEquals(1, lines.size());
		assertTrue(lines.get(0), lines.get(0).contains("2.5 full potions"));
	}

	@Test
	public void playtimeInTicksBecomesHours()
	{
		StatDef playtime = catalog.get(Stats.PLAYTIME);
		assertEquals(StatUnit.TICKS, playtime.getUnit());

		// 6000 ticks is one hour at 0.6 seconds per tick.
		List<String> lines = Comparisons.forStat(playtime, 12_000, ONE_METRE_PER_TILE);

		assertEquals(1, lines.size());
		assertTrue(lines.get(0), lines.get(0).contains("2.0 hours"));
	}

	@Test
	public void smallCalorieTotalsAreMeasuredInBigMacs()
	{
		StatDef calories = catalog.get(Stats.CALORIES);
		List<String> lines = Comparisons.forStat(calories, 1_100, ONE_METRE_PER_TILE);

		assertEquals(1, lines.size());
		assertTrue(lines.get(0), lines.get(0).contains("2.0 Big Macs"));
	}

	@Test
	public void largerCalorieTotalsBecomeDaysOfEating()
	{
		StatDef calories = catalog.get(Stats.CALORIES);
		List<String> lines = Comparisons.forStat(calories, 10_000, ONE_METRE_PER_TILE);

		assertTrue(lines.get(0), lines.get(0).contains("5.0 days of eating"));
	}

	@Test
	public void hugeCalorieTotalsBecomeBodyFat()
	{
		StatDef calories = catalog.get(Stats.CALORIES);
		List<String> lines = Comparisons.forStat(calories, 350_000, ONE_METRE_PER_TILE);

		assertTrue(lines.get(0), lines.get(0).contains("100.0 pounds of body fat"));
	}

	@Test
	public void caloriesFormatWithTheirUnit()
	{
		assertEquals("12,500 kcal", catalog.get(Stats.CALORIES).format(12_500));
	}

	@Test
	public void tickDurationsFormatAsHumanTime()
	{
		assertEquals("30s", StatUnit.formatDuration(50));
		assertEquals("1h 0m", StatUnit.formatDuration(6_000));
		assertEquals("1d 0h", StatUnit.formatDuration(6_000 * 24));
	}
}

package com.woodycode23.lifetracker.stats;

import java.time.LocalDate;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class AccountStatsTest
{
	private static final LocalDate TODAY = LocalDate.of(2026, 7, 30);

	private AccountStats stats;

	@Before
	public void setUp()
	{
		stats = new AccountStats();
		stats.ensureInitialised();
	}

	@Test
	public void addAccumulatesLifetimeDayAndMonthTogether()
	{
		stats.add(Stats.TILES_WALKED, 10, TODAY);
		stats.add(Stats.TILES_WALKED, 5, TODAY);

		assertEquals(15, stats.lifetime(Stats.TILES_WALKED));
		assertEquals(15, stats.value(Stats.TILES_WALKED, Period.DAY, TODAY));
		assertEquals(15, stats.value(Stats.TILES_WALKED, Period.YEAR, TODAY));
	}

	@Test
	public void dayViewExcludesYesterdayButWeekIncludesIt()
	{
		stats.add(Stats.TILES_WALKED, 100, TODAY.minusDays(1));
		stats.add(Stats.TILES_WALKED, 7, TODAY);

		assertEquals(7, stats.value(Stats.TILES_WALKED, Period.DAY, TODAY));
		assertEquals(107, stats.value(Stats.TILES_WALKED, Period.WEEK, TODAY));
	}

	@Test
	public void weekWindowDropsTheEighthDayBack()
	{
		stats.add(Stats.TILES_WALKED, 50, TODAY.minusDays(7));
		stats.add(Stats.TILES_WALKED, 3, TODAY.minusDays(6));

		assertEquals(3, stats.value(Stats.TILES_WALKED, Period.WEEK, TODAY));
	}

	@Test
	public void seriesIsOldestToNewestAndAlignsToToday()
	{
		stats.add(Stats.TILES_WALKED, 4, TODAY.minusDays(2));
		stats.add(Stats.TILES_WALKED, 9, TODAY);

		long[] series = stats.series(Stats.TILES_WALKED, Period.WEEK, TODAY);

		assertEquals(7, series.length);
		assertEquals(4, series[4]);
		assertEquals(0, series[5]);
		assertEquals(9, series[6]);
	}

	/** The whole point of the tiered design: pruning detail must not cost totals. */
	@Test
	public void pruningDropsDailyDetailButKeepsMonthlyAndLifetimeExact()
	{
		LocalDate old = TODAY.minusDays(AccountStats.DAILY_RETENTION_DAYS + 5);
		stats.add(Stats.TILES_WALKED, 1_000, old);
		stats.add(Stats.TILES_WALKED, 20, TODAY);

		stats.prune(TODAY);

		assertEquals(0, stats.value(Stats.TILES_WALKED, Period.MONTH, old));
		assertEquals(1_020, stats.lifetime(Stats.TILES_WALKED));
		assertEquals(1_000, stats.value(Stats.TILES_WALKED, Period.YEAR, old));
		assertEquals(20, stats.value(Stats.TILES_WALKED, Period.DAY, TODAY));
	}

	@Test
	public void recentDaysSurvivePruning()
	{
		stats.add(Stats.TILES_WALKED, 42, TODAY.minusDays(10));
		stats.prune(TODAY);

		assertEquals(42, stats.value(Stats.TILES_WALKED, Period.MONTH, TODAY));
	}

	@Test
	public void consecutiveDaysBuildAStreakAndAGapResetsIt()
	{
		stats.touchDay(TODAY.minusDays(2));
		stats.touchDay(TODAY.minusDays(1));
		stats.touchDay(TODAY);

		assertEquals(3, stats.currentStreak(TODAY));
		assertEquals(3, stats.bestStreak());

		stats.touchDay(TODAY.plusDays(5));

		assertEquals(1, stats.currentStreak(TODAY.plusDays(5)));
		assertEquals(3, stats.bestStreak());
	}

	@Test
	public void touchingTheSameDayTwiceDoesNotAdvanceTheStreak()
	{
		stats.touchDay(TODAY);
		stats.touchDay(TODAY);

		assertEquals(1, stats.currentStreak(TODAY));
	}

	/** A streak that has since lapsed must read as broken, not frozen at its last value. */
	@Test
	public void lapsedStreakReadsAsZero()
	{
		stats.touchDay(TODAY.minusDays(1));
		stats.touchDay(TODAY);

		assertEquals(2, stats.currentStreak(TODAY));
		assertEquals(2, stats.currentStreak(TODAY.plusDays(1)));
		assertEquals(0, stats.currentStreak(TODAY.plusDays(2)));
	}

	@Test
	public void recordsKeepTheBestSingleDay()
	{
		stats.add(Stats.TILES_WALKED, 500, TODAY.minusDays(1));
		stats.refreshRecords(TODAY.minusDays(1));

		stats.add(Stats.TILES_WALKED, 100, TODAY);
		stats.refreshRecords(TODAY);

		AccountStats.DayRecord record = stats.record(Stats.TILES_WALKED);
		assertNotNull(record);
		assertEquals(500, record.value);
		assertEquals("2026-07-29", record.day);
	}

	@Test
	public void trackedStatIdsListsOnlyStatsWithHistory()
	{
		stats.add(Stats.TILES_WALKED, 1, TODAY);

		assertTrue(stats.trackedStatIds().contains(Stats.TILES_WALKED));
		assertTrue(!stats.trackedStatIds().contains(Stats.TILES_SAILED));
	}

	/** A category reset must clear every view of that stat, not just today's. */
	@Test
	public void removeStatsErasesLifetimeBucketsAndRecords()
	{
		stats.add(Stats.TILES_WALKED, 100, TODAY.minusDays(3));
		stats.add(Stats.TILES_WALKED, 50, TODAY);
		stats.refreshRecords(TODAY);
		stats.setMilestoneIndex(Stats.TILES_WALKED, 2);

		stats.removeStats(java.util.Collections.singletonList(Stats.TILES_WALKED));

		assertEquals(0, stats.lifetime(Stats.TILES_WALKED));
		assertEquals(0, stats.value(Stats.TILES_WALKED, Period.DAY, TODAY));
		assertEquals(0, stats.value(Stats.TILES_WALKED, Period.WEEK, TODAY));
		assertEquals(0, stats.value(Stats.TILES_WALKED, Period.YEAR, TODAY));
		assertNull(stats.record(Stats.TILES_WALKED));
		assertEquals(-1, stats.milestoneIndex(Stats.TILES_WALKED));
	}

	@Test
	public void removeStatsLeavesOtherStatsAlone()
	{
		stats.add(Stats.TILES_WALKED, 100, TODAY);
		stats.add(Stats.POTION_DOSES, 7, TODAY);

		stats.removeStats(java.util.Collections.singletonList(Stats.TILES_WALKED));

		assertEquals(0, stats.lifetime(Stats.TILES_WALKED));
		assertEquals(7, stats.lifetime(Stats.POTION_DOSES));
	}

	@Test
	public void zeroAmountsAreIgnored()
	{
		stats.add(Stats.TILES_WALKED, 0, TODAY);

		assertTrue(stats.trackedStatIds().isEmpty());
	}
}

package com.woodycode23.lifetracker.stats;

