package com.woodycode23.lifetracker.trackers;

import com.google.inject.Guice;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.itemstats.ItemStatChanges;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import org.junit.Before;
import org.junit.Test;

/**
 * Pins the test used to decide whether a consumed item is actually a consumable.
 *
 * <p>An earlier version decided by elimination: anything that was not a potion and left the
 * inventory during a consume was food. Equipping gear also removes an item from the inventory, so
 * in combat every weapon and armour switch was recorded as a meal. Real captured data included
 * "Tumeken's shadow x10" and "Dharok's platebody x1" as food.
 *
 * <p>The fix is to ask the game instead of inferring: an item counts only if the client's own
 * consumable table has an effect for it. These assertions are what make that safe to rely on.
 */
public class ConsumableIdentificationTest
{
	private ItemStatChanges stats;

	@Before
	public void setUp()
	{
		stats = Guice.createInjector().getInstance(ItemStatChanges.class);
	}

	@Test
	public void realFoodsAreRecognised()
	{
		assertNotNull("shark", stats.get(ItemID.SHARK));
	}

	@Test
	public void equipmentIsNotAConsumable()
	{
		assertNull("occult necklace", stats.get(ItemID.OCCULT_NECKLACE));
		assertNull("tumeken's shadow", stats.get(ItemID.TUMEKENS_SHADOW));
	}

	/**
	 * A watering can is named "Watering can(7)", which matches the dose suffix that identifies a
	 * potion. Captured data had it logged as 7 potion doses drunk.
	 */
	@Test
	public void wateringCansAreNotPotions()
	{
		assertNull("watering can", stats.get(ItemID.WATERING_CAN_7));
		assertNull("empty watering can", stats.get(ItemID.WATERING_CAN_0));
	}
}

package com.woodycode23.lifetracker.trackers;

import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class ConsumeDetectorTest
{
	// Divine super combat potion, the potion that exposed the ordering bug.
	private static final int DIVINE_SCB_4 = 23685;
	private static final int DIVINE_SCB_3 = 23688;
	private static final int DIVINE_SCB_1 = 23694;
	private static final int VIAL = 229;
	private static final int SHARK = 385;
	private static final int COINS = 995;
	private static final int SCYTHE = 22325;

	private static final String DIVINE_SCB = "Divine super combat potion";

	private static final int WINDOW = 1;

	private ConsumeDetector detector;

	@Before
	public void setUp()
	{
		detector = new ConsumeDetector(itemId -> {
			switch (itemId)
			{
				case DIVINE_SCB_4:
					return new ConsumeDetector.PotionInfo(DIVINE_SCB, 4);
				case DIVINE_SCB_3:
					return new ConsumeDetector.PotionInfo(DIVINE_SCB, 3);
				case DIVINE_SCB_1:
					return new ConsumeDetector.PotionInfo(DIVINE_SCB, 1);
				default:
					return null;
			}
		}, itemId -> itemId == DIVINE_SCB_4 || itemId == DIVINE_SCB_3 || itemId == DIVINE_SCB_1 || itemId == SHARK, WINDOW);
	}

	private static Map<Integer, Integer> inventory(int... idQuantityPairs)
	{
		Map<Integer, Integer> out = new HashMap<>();
		for (int i = 0; i < idQuantityPairs.length; i += 2)
		{
			out.put(idQuantityPairs[i], idQuantityPairs[i + 1]);
		}
		return out;
	}

	private void baseline(int tick, Map<Integer, Integer> starting)
	{
		assertTrue(detector.onInventory(tick, starting).isEmpty());
	}

	@Test
	public void animationBeforeInventoryCountsTheSip()
	{
		baseline(100, inventory(DIVINE_SCB_4, 1));

		detector.onAnimation(101);
		ConsumeDetector.Result result = detector.onInventory(101, inventory(DIVINE_SCB_3, 1));

		assertEquals(1, result.totalDoses);
		assertEquals(Integer.valueOf(1), result.potionDoses.get(DIVINE_SCB));
	}

	/**
	 * The regression. The client may post the inventory update before the animation, and the
	 * original implementation discarded the diff outright in that case, losing every sip.
	 */
	@Test
	public void inventoryBeforeAnimationStillCountsTheSip()
	{
		baseline(100, inventory(DIVINE_SCB_4, 1));

		ConsumeDetector.Result onInventory = detector.onInventory(101, inventory(DIVINE_SCB_3, 1));
		assertTrue("diff must be held, not counted yet", onInventory.isEmpty());

		ConsumeDetector.Result onAnimation = detector.onAnimation(101);

		assertEquals(1, onAnimation.totalDoses);
		assertEquals(Integer.valueOf(1), onAnimation.potionDoses.get(DIVINE_SCB));
	}

	@Test
	public void animationArrivingOneTickLateStillCounts()
	{
		baseline(100, inventory(DIVINE_SCB_4, 1));

		detector.onInventory(101, inventory(DIVINE_SCB_3, 1));
		ConsumeDetector.Result result = detector.onAnimation(102);

		assertEquals(1, result.totalDoses);
	}

	/** The gate that keeps banking, looting and trading out of the numbers. */
	@Test
	public void inventoryChangeWithNoAnimationIsNeverCounted()
	{
		baseline(100, inventory(DIVINE_SCB_4, 1, SHARK, 5));

		ConsumeDetector.Result result = detector.onInventory(101, inventory(SHARK, 2));
		assertTrue(result.isEmpty());

		// Much later, an unrelated consume must not retroactively bank the stale diff.
		ConsumeDetector.Result later = detector.onAnimation(200);
		assertTrue(later.isEmpty());
	}

	@Test
	public void finishingTheLastDoseCountsAsASipAndLeavesAVial()
	{
		baseline(100, inventory(DIVINE_SCB_1, 1));

		detector.onAnimation(101);
		ConsumeDetector.Result result = detector.onInventory(101, inventory(VIAL, 1));

		assertEquals(1, result.totalDoses);
		assertEquals("the empty vial is not food", 0, result.foodEaten);
	}

	@Test
	public void eatingFoodCountsAsFoodNotAsAPotion()
	{
		baseline(100, inventory(SHARK, 3));

		detector.onAnimation(101);
		ConsumeDetector.Result result = detector.onInventory(101, inventory(SHARK, 2));

		assertEquals(1, result.foodEaten);
		assertEquals(0, result.totalDoses);
	}

	@Test
	public void comboEatingInOneTickCountsBothItems()
	{
		baseline(100, inventory(SHARK, 1, DIVINE_SCB_4, 1));

		detector.onAnimation(101);
		ConsumeDetector.Result food = detector.onInventory(101, inventory(DIVINE_SCB_4, 1));
		ConsumeDetector.Result sip = detector.onInventory(101, inventory(DIVINE_SCB_3, 1));

		assertEquals(1, food.foodEaten);
		assertEquals(1, sip.totalDoses);
	}

	/** Two inventory updates land before the animation; neither may be dropped. */
	@Test
	public void multiplePendingDiffsAllResolveOnTheAnimation()
	{
		baseline(100, inventory(SHARK, 1, DIVINE_SCB_4, 1));

		detector.onInventory(101, inventory(DIVINE_SCB_4, 1));
		detector.onInventory(101, inventory(DIVINE_SCB_3, 1));
		ConsumeDetector.Result result = detector.onAnimation(101);

		assertEquals(1, result.foodEaten);
		assertEquals(1, result.totalDoses);
	}

	/** A stack falling by more than one during a sip is not a meal. */
	@Test
	public void spendingCoinsDuringASipIsNotCountedAsFood()
	{
		baseline(100, inventory(DIVINE_SCB_4, 1, COINS, 1000));

		detector.onAnimation(101);
		ConsumeDetector.Result result = detector.onInventory(101, inventory(DIVINE_SCB_3, 1, COINS, 900));

		assertEquals(1, result.totalDoses);
		assertEquals(0, result.foodEaten);
	}

	/**
	 * The bug that prompted the positive consumable test. Equipping gear removes it from the
	 * inventory, and the old "not a potion, dropped by one" rule recorded that as a meal.
	 */
	@Test
	public void equippingGearDuringAConsumeIsNotFood()
	{
		baseline(100, inventory(SHARK, 1, SCYTHE, 1));

		detector.onAnimation(101);
		ConsumeDetector.Result result = detector.onInventory(101, inventory(SHARK, 1));

		assertEquals("equipping a scythe is not eating", 0, result.foodEaten);
		assertFalse(result.consumedItems.containsKey(SCYTHE));
	}

	/** Calories need the specific item, not just the tally, so the diff must name what left. */
	@Test
	public void consumedItemsNamesTheFoodThatLeft()
	{
		baseline(100, inventory(SHARK, 3));

		detector.onAnimation(101);
		ConsumeDetector.Result result = detector.onInventory(101, inventory(SHARK, 2));

		assertEquals(1, result.consumedItems.size());
		assertEquals(Integer.valueOf(1), result.consumedItems.get(SHARK));
	}

	@Test
	public void consumedItemsNamesTheDoseThatWasDrunk()
	{
		baseline(100, inventory(DIVINE_SCB_4, 1));

		detector.onAnimation(101);
		ConsumeDetector.Result result = detector.onInventory(101, inventory(DIVINE_SCB_3, 1));

		assertEquals(Integer.valueOf(1), result.consumedItems.get(DIVINE_SCB_4));
	}

	@Test
	public void consumedItemsExcludesStacksThatMerelyShrank()
	{
		baseline(100, inventory(DIVINE_SCB_4, 1, COINS, 1000));

		detector.onAnimation(101);
		ConsumeDetector.Result result = detector.onInventory(101, inventory(DIVINE_SCB_3, 1, COINS, 900));

		assertFalse(result.consumedItems.containsKey(COINS));
	}

	@Test
	public void firstSnapshotIsABaselineAndCountsNothing()
	{
		detector.onAnimation(100);
		ConsumeDetector.Result result = detector.onInventory(100, inventory(DIVINE_SCB_4, 1));

		assertTrue(result.isEmpty());
	}

	@Test
	public void resetDropsPendingStateSoALogoutCannotLeakIntoTheNextSession()
	{
		baseline(100, inventory(DIVINE_SCB_4, 1));
		detector.onInventory(101, inventory(DIVINE_SCB_3, 1));

		detector.reset();

		assertTrue(detector.onAnimation(101).isEmpty());
	}
}

package com.woodycode23.lifetracker.trackers;

import com.google.inject.Guice;
import com.google.inject.Injector;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.itemstats.Effect;
import net.runelite.client.plugins.itemstats.ItemStatChanges;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import org.junit.Test;

/**
 * Proves the plugin can reach the game's heal data from its own injector.
 *
 * <p>The obvious dependency, {@code ItemStatChangesService}, is bound inside the core Item Stats
 * plugin's {@code configure} method. Core plugins such as Status Bars can inject it because they
 * share that injector; a sideloaded plugin gets its own and the binding is absent, which failed the
 * whole plugin at instantiation with "No implementation for ItemStatChangesService was bound".
 *
 * <p>{@link ItemStatChanges} itself is a concrete singleton whose no-argument constructor is
 * package-private rather than private, so Guice can construct it just in time with no explicit
 * binding. This test is here because that is a claim about Guice's behaviour, and the last claim
 * about Guice's behaviour in this plugin was wrong.
 */
public class ItemStatsBindingTest
{
	@Test
	public void guiceCanConstructItemStatChangesWithoutAnyBinding()
	{
		Injector injector = Guice.createInjector();

		ItemStatChanges changes = injector.getInstance(ItemStatChanges.class);

		assertNotNull(changes);
	}

	@Test
	public void itIsASingletonSoTheTableIsBuiltOnce()
	{
		Injector injector = Guice.createInjector();

		assertSame(injector.getInstance(ItemStatChanges.class), injector.getInstance(ItemStatChanges.class));
	}

	@Test
	public void knownFoodHasAnEffect()
	{
		ItemStatChanges changes = Guice.createInjector().getInstance(ItemStatChanges.class);

		Effect shark = changes.get(ItemID.SHARK);

		assertNotNull("shark should have a food effect", shark);
	}

	@Test
	public void unknownItemHasNoEffectRatherThanThrowing()
	{
		ItemStatChanges changes = Guice.createInjector().getInstance(ItemStatChanges.class);

		assertNotNull(changes);
		changes.get(ItemID.COINS);
	}
}

package com.woodycode23.lifetracker.trackers;

import net.runelite.api.Prayer;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class PrayerTrackerTest
{
	@Test
	public void joiningWordsStayLowercase()
	{
		assertEquals("Protect from Melee", PrayerTracker.displayName(Prayer.PROTECT_FROM_MELEE));
		assertEquals("Protect from Missiles", PrayerTracker.displayName(Prayer.PROTECT_FROM_MISSILES));
