package com.woodycode23.lifetracker.ui;

import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.time.LocalDate;
import javax.imageio.ImageIO;
import com.woodycode23.lifetracker.LifeTrackerConfig;
import com.woodycode23.lifetracker.stats.StatCatalog;
import com.woodycode23.lifetracker.stats.StatSelection;
import com.woodycode23.lifetracker.stats.StatStore;
import com.woodycode23.lifetracker.stats.Stats;
import static org.junit.Assert.assertTrue;
import org.junit.Assume;
import org.junit.Test;

/**
 * Builds the panel against a store filled with realistic numbers and paints it to a PNG.
 *
 * <p>Doubles as a smoke test: constructing and laying out the whole panel exercises every custom
 * painted component, so a null layout or a broken paint shows up here rather than after a client
 * restart. Set {@code lifetracker.preview.out} to write the image somewhere you can look at it.
 */
public class PanelPreviewTest
{
	private static final int WIDTH = 225;
	private static final int HEIGHT = 900;

	/**
	 * Opt in, via the output property.
	 *
	 * <p>These tests paint real Swing components, which behaves fine here but is the sort of thing
	 * that can differ in someone else's build container. The Plugin Hub runs `gradlew build` on
	 * submission, and a rendering quirk there would fail the whole submission over a developer
	 * tool. Skipping unless a path is asked for keeps that risk at zero.
	 */
	private static void requirePreviewRequested(String path)
	{
		Assume.assumeTrue("set -Dlifetracker.preview*.out to render", path != null && !path.isEmpty());
	}

	@Test
	public void panelBuildsAndPaints() throws Exception
	{
		requirePreviewRequested(System.getProperty("lifetracker.preview.out"));

		LocalDate today = LocalDate.now();

		StatCatalog catalog = new StatCatalog();
		StatStore store = new StatStore(null, new Gson());
		store.activate("BlG WOODY", today);

		seed(store, today, catalog);

		LifeTrackerConfig config = new LifeTrackerConfig()
		{
		};

		StatSelection selection = new StatSelection(null, new Gson());
		selection.load();

		LifeTrackerPanel panel = new LifeTrackerPanel(store, catalog, selection, config, () -> {
		});

		// The panel defers layout to the Swing thread, so let those runnables land first.
		javax.swing.SwingUtilities.invokeAndWait(() -> {
		});

		// DynamicGridLayout scales children by parentHeight/preferredHeight, so the panel must be
		// sized to what it actually wants. Forcing an arbitrary height squashes every card.
		int height = Math.max(HEIGHT, panel.getPreferredSize().height);
		panel.setSize(WIDTH, height);
		panel.doLayout();
		layoutTree(panel);

		BufferedImage image = new BufferedImage(WIDTH, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		try
		{
			panel.paint(g);
		}
		finally
		{
			g.dispose();
		}

		// Absent shows up as an empty string, not null, when the build forwards the property.
		String out = System.getProperty("lifetracker.preview.out");
		if (out != null && !out.isEmpty())
		{
			File file = new File(out);
			ImageIO.write(image, "png", file);
			assertTrue(file.length() > 0);
		}
	}

	@Test
	public void trackingPageBuildsAndPaints() throws Exception
	{
		requirePreviewRequested(System.getProperty("lifetracker.preview.tracking.out"));

		LocalDate today = LocalDate.now();

		StatCatalog catalog = new StatCatalog();
		StatStore store = new StatStore(null, new Gson());
		store.activate("BlG WOODY", today);
		seed(store, today, catalog);

		StatSelection selection = new StatSelection(null, new Gson());
		selection.load();
		selection.setVisible(Stats.TILES_OTHER, false);
		selection.setVisible(Stats.LOW_ALCHS, false);

		TrackingPage tracking = new TrackingPage(catalog, store, selection, () -> {
		});
		tracking.setBackground(Palette.BACKGROUND);

		int height = Math.max(600, tracking.getPreferredSize().height);
		tracking.setSize(WIDTH, height);
		layoutTree(tracking);

		BufferedImage image = new BufferedImage(WIDTH, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		try
		{
			g.setColor(Palette.BACKGROUND);
			g.fillRect(0, 0, WIDTH, height);
			tracking.paint(g);
		}
		finally
		{
			g.dispose();
		}

		String out = System.getProperty("lifetracker.preview.tracking.out");
		if (out != null && !out.isEmpty())
		{
			File file = new File(out);
			ImageIO.write(image, "png", file);
			assertTrue(file.length() > 0);
		}
	}

	/** Swing only lays out realised containers, so walk the tree and force it. */
	private static void layoutTree(java.awt.Container container)
	{
		container.doLayout();
		for (java.awt.Component child : container.getComponents())
		{
			if (child instanceof java.awt.Container)
			{
				layoutTree((java.awt.Container) child);
			}
		}
	}

	private static void seed(StatStore store, LocalDate today, StatCatalog catalog)
	{
		long[] dailyTiles = {4200, 3100, 5600, 900, 6100, 2400, 4800};
		for (int i = 0; i < dailyTiles.length; i++)
		{
			LocalDate day = today.minusDays(dailyTiles.length - 1L - i);
			store.add(Stats.TILES_TOTAL, dailyTiles[i], day);
			store.add(Stats.TILES_RAN, (long) (dailyTiles[i] * 0.8), day);
			store.add(Stats.TILES_WALKED, (long) (dailyTiles[i] * 0.15), day);
			store.add(Stats.TILES_SAILED, (long) (dailyTiles[i] * 0.05), day);
			store.add(Stats.TELEPORTS, 12, day);

			store.add(Stats.CALORIES, 12_400 + i * 900L, day);
			store.add(Stats.POTION_DOSES, 26, day);
			store.add(catalog.registerPotion("Stamina potion"), 12, day);
			store.add(catalog.registerPotion("Divine super combat potion"), 8, day);
			store.add(catalog.registerPotion("Prayer potion"), 6, day);
			store.add(Stats.FOOD_EATEN, 41, day);
			store.add(catalog.registerFood("Shark"), 22, day);
			store.add(catalog.registerFood("Saradomin brew"), 11, day);
			store.add(catalog.registerFood("Cooked karambwan"), 8, day);
			store.add(Stats.FOOD_HEALED, 820, day);

			store.add(Stats.PRAYER_OVERHEAD_UPTIME, 5400, day);
			store.add(Stats.PRAYER_ANY_UPTIME, 8200, day);
			store.add(Stats.PRAYER_POINTS_DRAINED, 640, day);
			store.add(catalog.registerPrayer("Protect from Melee", true), 3100, day);
			store.add(catalog.registerPrayer("Rigour", false), 7400, day);

			store.add(Stats.PLAYTIME, 21000, day);
			store.add(Stats.ACTIVE_TIME, 15400, day);
			store.add(Stats.IDLE_TIME, 5600, day);
			store.add(Stats.LOGINS, 3, day);

			store.add(Stats.DAMAGE_DEALT, 18400, day);
			store.add(Stats.DAMAGE_TAKEN, 6100, day);
			store.add(Stats.DEATHS, 1, day);
			store.add(Stats.NPC_KILLS, 210, day);
			store.add(Stats.SPECS_USED, 34, day);
			store.add(Stats.HIGH_ALCHS, 60, day);
		}

		for (int i = 0; i < 5; i++)
		{
			store.get(store.getActiveAccountKey()).touchDay(today.minusDays(4L - i));
		}
	}
}
